11	// enrichEntry populates git and project type metadata for a directory entry
12	func enrichEntry(entry *Entry) {
13		entry.ProjectType = detectProjectType(entry.Path)
14		detectGitStatus(entry)
15		if entry.IsGitRepo {
16			return
17		}
18		// For non-git directories, find nested git repos (depth ≤ 3)
19		entry.SubRepoPaths = detectSubRepoPaths(entry.Path, 3)
20	}
21	
22	// detectProjectType detects the project type by looking for signature files
23	func detectProjectType(path string) string {
24		signatures := []struct {
25			file     string
26			projType string
27		}{
28			{"go.mod", "Go"},
29			{"Cargo.toml", "Rust"},
30			{"package.json", "Node"},
31			{"pyproject.toml", "Python"},
32			{"requirements.txt", "Python"},
33			{"pom.xml", "Java"},
34			{"build.gradle", "Java"},
35			{"Gemfile", "Ruby"},
36			{"composer.json", "PHP"},
37			{"mix.exs", "Elixir"},
38			{"Makefile", "Make"},
39			{"Dockerfile", "Docker"},
40		}
41	
42		for _, sig := range signatures {
43			if _, err := os.Stat(filepath.Join(path, sig.file)); err == nil {
44				return sig.projType
45			}
46		}
47		return ""
48	}
49	
50	// detectGitStatus populates git-related fields on the entry
51	func detectGitStatus(entry *Entry) {
52		gitDir := filepath.Join(entry.Path, ".git")
53		if _, err := os.Stat(gitDir); os.IsNotExist(err) {
54			return
55		}
56		entry.IsGitRepo = true
57	
58		// Get current branch
59		if out, err := execGit(entry.Path, "rev-parse", "--abbrev-ref", "HEAD"); err == nil {
60			entry.GitBranch = strings.TrimSpace(out)
61		}
62	
63		// Get remote URL: store display path and full normalized URL
64		if out, err := execGit(entry.Path, "remote", "get-url", "origin"); err == nil {
65			rawURL := strings.TrimSpace(out)
66			entry.GitRemote = extractRemotePath(rawURL)
67			entry.GitRemoteURL = normalizeRemoteURL(rawURL)
68		}
69	
70		// Get modified/untracked counts from porcelain status
71		if out, err := execGit(entry.Path, "status", "--porcelain"); err == nil {
72			for line := range strings.SplitSeq(out, "\n") {
73				if len(line) < 2 {
74					continue
75				}
76				xy := line[:2]
77				if xy == "??" {
78					entry.GitUntracked++
79				} else {
80					entry.GitModified++
81				}
82			}
83		}
84	
85		// Get unpushed commits count
86		if out, err := execGit(entry.Path, "rev-list", "--count", "@{u}..HEAD"); err == nil {
87			_, _ = fmt.Sscanf(strings.TrimSpace(out), "%d", &entry.GitUnpushed)
88		}
89	
90		// Get unpulled commits count
91		if out, err := execGit(entry.Path, "rev-list", "--count", "HEAD..@{u}"); err == nil {
92			_, _ = fmt.Sscanf(strings.TrimSpace(out), "%d", &entry.GitUnpulled)
93		}
94	}
95	
96	// extractRemotePath strips the server from a git remote URL and returns only the path.
97	// Examples:
98	//
99	//	"https://gitlab.com/group/project.git" → "group/project"
100	//	"git@gitlab.com:group/project.git"     → "group/project"
101	func extractRemotePath(rawURL string) string {
102		// SCP-like syntax: git@host:path — colon must not be followed by "//"
103		if idx := strings.Index(rawURL, ":"); idx != -1 && !strings.Contains(rawURL[:idx], "/") {
104			after := rawURL[idx+1:]
105			if !strings.HasPrefix(after, "//") {
106				return strings.TrimSuffix(after, ".git")
107			}
108		}
109		// URL syntax: scheme://host/path
110		if idx := strings.Index(rawURL, "://"); idx != -1 {
111			rest := rawURL[idx+3:]
112			if slash := strings.Index(rest, "/"); slash != -1 {
113				return strings.TrimSuffix(rest[slash+1:], ".git")
114			}
115		}
116		return rawURL
117	}
118	
119	// normalizeRemoteURL converts any git remote URL to a plain HTTPS URL suitable for a browser.
120	// Examples:
121	//
122	//	"git@gitlab.com:group/project.git"            → "https://gitlab.com/group/project"
123	//	"https://token@gitlab.com/group/project.git"  → "https://gitlab.com/group/project"
124	func normalizeRemoteURL(rawURL string) string {
125		// SCP-like syntax: git@host:path
126		if idx := strings.Index(rawURL, ":"); idx != -1 && !strings.Contains(rawURL[:idx], "/") {
127			after := rawURL[idx+1:]
128			if !strings.HasPrefix(after, "//") {
129				host := rawURL[:idx]
130				if at := strings.Index(host, "@"); at != -1 {
131					host = host[at+1:]
132				}
133				return "https://" + host + "/" + strings.TrimSuffix(after, ".git")
134			}
135		}
136		// URL syntax: strip credentials and .git suffix
137		if idx := strings.Index(rawURL, "://"); idx != -1 {
138			scheme := rawURL[:idx]
139			rest := rawURL[idx+3:]
140			if at := strings.Index(rest, "@"); at != -1 {
141				if slash := strings.Index(rest, "/"); slash == -1 || at < slash {
142					rest = rest[at+1:]
143				}
144			}
145			return scheme + "://" + strings.TrimSuffix(rest, ".git")
146		}
147		return rawURL
148	}
149	
150	// execGit runs a git command in the given directory and returns stdout
151	func execGit(dir string, args ...string) (string, error) {
152		cmd := exec.Command("git", args...)
153		cmd.Dir = dir
154		out, err := cmd.Output()
155		if err != nil {
156			return "", err
157		}
158		return string(out), nil
159	}
160	
161	// detectSubRepoPaths walks a directory up to maxDepth and returns paths of git repos found.
162	func detectSubRepoPaths(basePath string, maxDepth int) []string {
163		var repos []string
164		walkSubRepos(basePath, 0, maxDepth, &repos)
165		return repos
166	}
167	
168	// walkSubRepos is the recursive helper for detectSubRepoPaths
169	func walkSubRepos(dir string, depth, maxDepth int, repos *[]string) {
170		if depth > maxDepth {
171			return
172		}
173		gitDir := filepath.Join(dir, ".git")
174		if _, err := os.Stat(gitDir); err == nil {
175			*repos = append(*repos, dir)
176			return // don't recurse into nested repos
177		}
178		entries, err := os.ReadDir(dir)
179		if err != nil {
180			return
181		}
182		for _, e := range entries {
183			if !e.IsDir() || strings.HasPrefix(e.Name(), ".") {
184				continue
185			}
186			walkSubRepos(filepath.Join(dir, e.Name()), depth+1, maxDepth, repos)
187		}
188	}
