21	// clearFooterInfoCmd returns a command that clears the footer info message after a delay.
22	func clearFooterInfoCmd() tea.Cmd {
23		return tea.Tick(3*time.Second, func(time.Time) tea.Msg {
24			return clearFooterInfoMsg{}
25		})
26	}
27	
28	// clearSyncSummaryCmd drops a finished sync's summary from the footer after the
29	// same three seconds every other footer message gets (Rule 128).
30	func clearSyncSummaryCmd() tea.Cmd {
31		return tea.Tick(3*time.Second, func(time.Time) tea.Msg {
32			return clearSyncSummaryMsg{}
33		})
34	}
35	
36	// syncSpec is what a batch of syncs needs from the model, copied out before the
37	// first command runs (Rule 110).
38	type syncSpec struct {
39		gitlabURL string
40		// token loads the configured GitLab token, at most once for the batch. It
41		// is a closure rather than the token itself so the keyring read happens on
42		// a command's goroutine — Update does no I/O — and so twelve repositories
43		// do not produce twelve reads.
44		token func() string
45		jobs  int
46	}
47	
48	// tokenLoader returns a function that loads the GitLab token once and then
49	// answers from memory. A missing token is not an error: a public repository
50	// fetches without one, and a private one fails with git's own reason.
51	func tokenLoader(storage credentials.Storage, gitlabURL string) func() string {
52		if storage == nil || gitlabURL == "" {
53			return func() string { return "" }
54		}
55		var once sync.Once
56		var token string
57		return func() string {
58			once.Do(func() {
59				loaded, err := gitlab.NewAuth(storage).LoadCredentials(gitlabURL)
60				if err != nil {
61					log.Printf("ERROR [workspaces] loading the sync token: %v", err)
62					return
63				}
64				token = loaded
65			})
66			return token
67		}
68	}
69	
70	// syncOneRepoCmd syncs a single repository, bounded by the batch's semaphore.
71	func syncOneRepoCmd(repoPath string, spec syncSpec, sem chan struct{}) tea.Cmd {
72		return tea.Sequence(
73			func() tea.Msg { return WorkspaceSyncStartingMsg{RepoPath: repoPath} },
74			func() tea.Msg {
75				sem <- struct{}{}
76				defer func() { <-sem }()
77	
78				msg := WorkspaceSyncCompleteMsg{RepoPath: repoPath}
79				remote, err := git.RemoteURL(repoPath)
80				if err != nil {
81					msg.Error = err
82					return msg
83				}
84	
85				result, err := git.Sync(repoPath, git.SyncOptions{
86					Token: tokenForRemote(remote, spec.gitlabURL, spec.token),
87				})
88				msg.Error = err
89				msg.Outcome = result.Outcome
90				msg.Behind = result.Behind
91				msg.Reason = result.Reason
92	
93				// Re-read the repository whatever happened. A refused sync fetched
94				// all the same, so its counts are current now even though nothing
95				// merged — which is the answer to D35 and the reason a refusal is
96				// still worth something.
97				msg.Status = readGitStatus(repoPath)
98				return msg
99			},
100		)
101	}
102	
103	// batchSyncCmd syncs every path through a pool of gitlab.pull.parallel_jobs.
104	//
105	// The setting is shared with the explorer's clone deliberately: both are "how
106	// many git network operations at once", and one number the user can reason
107	// about beats two they have to keep in step.
108	func batchSyncCmd(repoPaths []string, spec syncSpec) tea.Cmd {
109		sem := make(chan struct{}, max(spec.jobs, 1))
110		cmds := make([]tea.Cmd, len(repoPaths))
111		for i, path := range repoPaths {
112			cmds[i] = syncOneRepoCmd(path, spec, sem)
113		}
114		return tea.Batch(cmds...)
115	}
116	
117	// readGitStatus re-reads one repository's git metadata.
118	func readGitStatus(repoPath string) Entry {
119		entry := Entry{Path: repoPath, IsDir: true}
120		detectGitStatus(&entry)
121		return entry
122	}
