124	// loadScanCacheCmd loads the workspace scan cache from disk asynchronously
125	func loadScanCacheCmd() tea.Cmd {
126		return func() tea.Msg {
127			c, err := cache.NewWorkspaceScanCache(config.CurrentContextName())
128			if err != nil {
129				return ScanCacheLoadedMsg{Cache: nil}
130			}
131			return ScanCacheLoadedMsg{Cache: c.GetAll()}
132		}
133	}
134	
135	// deleteScanCacheCmd removes the given repo paths from the disk cache (Rule 126: scan all purges cache)
136	func deleteScanCacheCmd(paths []string) tea.Cmd {
137		return func() tea.Msg {
138			c, err := cache.NewWorkspaceScanCache(config.CurrentContextName())
139			if err != nil {
140				return nil
141			}
142			for _, path := range paths {
143				_ = c.Delete(path)
144			}
145			return nil
146		}
147	}
