149	// scanOneRepoCmd scans a single git repo directory, using a semaphore to limit concurrency.
150	// It emits WorkspaceScanStartingMsg before scanning and WorkspaceScanCompleteMsg after.
151	func scanOneRepoCmd(repoPath string, opts scan.ScanOptions, sem chan struct{}) tea.Cmd {
152		return tea.Sequence(
153			func() tea.Msg {
154				return WorkspaceScanStartingMsg{RepoPath: repoPath}
155			},
156			func() tea.Msg {
157				sem <- struct{}{}
158				defer func() { <-sem }()
159	
160				scanner := scan.NewScanner(opts)
161				result, err := scanner.Scan(context.Background(), repoPath, scan.TargetDirectory)
162				if err != nil {
163					log.Printf("ERROR [workspaces] scan %s: %v", repoPath, err)
164					return WorkspaceScanCompleteMsg{
165						RepoPath: repoPath,
166						Error:    err,
167					}
168				}
169	
170				if len(result.Errors) > 0 && result.TotalFindings() == 0 {
171					combined := strings.Join(result.Errors, "; ")
172					log.Printf("ERROR [workspaces] scan errors for %s: %s", repoPath, combined)
173				}
174	
175				// Le verdict vient du scan et de nulle part ailleurs : la boucle
176				// « une finding dont Source vaut gitleaks » qui était ici ne voyait
177				// pas les secrets trouvés par Trivy, et ne savait pas dire qu'aucune
178				// étape n'avait cherché.
179				sensitive := result.SecretVerdict()
180	
181				entry := cache.WorkspaceScanEntry{
182					RepoPath:  repoPath,
183					Critical:  result.Counts.Critical,
184					High:      result.Counts.High,
185					Medium:    result.Counts.Medium,
186					Low:       result.Counts.Low,
187					Sensitive: sensitive,
188					ScannedAt: result.EndTime,
189				}
190	
191				wc, cErr := cache.NewWorkspaceScanCache(config.CurrentContextName())
192				if cErr != nil {
193					log.Printf("ERROR [workspaces] open cache: %v", cErr)
194				} else if sErr := wc.Set(repoPath, entry); sErr != nil {
195					log.Printf("ERROR [workspaces] cache set %s: %v", repoPath, sErr)
196				}
197	
198				if sErr := cache.SaveWorkspaceScanResult(repoPath, result); sErr != nil {
199					log.Printf("ERROR [workspaces] save full result %s: %v", repoPath, sErr)
200				}
201	
202				return WorkspaceScanCompleteMsg{
203					RepoPath:  repoPath,
204					Critical:  entry.Critical,
205					High:      entry.High,
206					Medium:    entry.Medium,
207					Low:       entry.Low,
208					Sensitive: sensitive,
209					ScannedAt: entry.ScannedAt,
210				}
211			},
212		)
213	}
214	
215	// batchScanCmd scans all provided repo paths in parallel using a worker pool
216	// of runtime.NumCPU()/2 workers (minimum 1).
217	func batchScanCmd(repoPaths []string, opts scan.ScanOptions) tea.Cmd {
218		numWorkers := runtime.NumCPU() / 2
219		if numWorkers < 1 {
220			numWorkers = 1
221		}
222		sem := make(chan struct{}, numWorkers)
223	
224		cmds := make([]tea.Cmd, len(repoPaths))
225		for i, path := range repoPaths {
226			cmds[i] = scanOneRepoCmd(path, opts, sem)
227		}
228		return tea.Batch(cmds...)
229	}
