17	// startSecurityScan launches a security scan on the selected entry using saved options.
18	// For git repos, scans the single repo. For directories with sub-repos, scans all sub-repos in parallel.
19	func (m Model) startSecurityScan() (tea.Model, tea.Cmd) {
20		opts := scan.OptionsFromConfig(m.config.Scan)
21	
22		if len(m.table.Items()) == 0 {
23			// Fallback: scan the current directory path
24			targetPath := m.currentPath
25			if targetPath == "" {
26				targetPath = m.getExpandedWorkspacesDir()
27			}
28			if targetPath == "" {
29				return m, nil
30			}
31			if m.busy(targetPath) {
32				m.footerInfo = busyMessage
33				return m, clearFooterInfoCmd()
34			}
35			delete(m.scanCache, targetPath)
36			return m, tea.Batch(deleteScanCacheCmd([]string{targetPath}), batchScanCmd([]string{targetPath}, opts))
37		}
38	
39		entry, ok := m.selectedEntry()
40		if !ok || !entry.IsDir {
41			return m, nil
42		}
43	
44		if entry.IsGitRepo {
45			if m.busy(entry.Path) {
46				m.footerInfo = busyMessage
47				return m, clearFooterInfoCmd()
48			}
49			delete(m.scanCache, entry.Path)
50			return m, tea.Batch(deleteScanCacheCmd([]string{entry.Path}), batchScanCmd([]string{entry.Path}, opts))
51		}
52	
53		// Non-git directory: scan all non-scanning nested git repos in parallel
54		if len(entry.SubRepoPaths) == 0 {
55			return m, nil
56		}
57	
58		var toScan []string
59		for _, repoPath := range entry.SubRepoPaths {
60			if !m.busy(repoPath) {
61				toScan = append(toScan, repoPath)
62			}
63		}
64	
65		if len(toScan) == 0 {
66			m.footerInfo = busyMessage
67			return m, clearFooterInfoCmd()
68		}
69	
70		for _, path := range toScan {
71			delete(m.scanCache, path)
72		}
73		return m, tea.Batch(deleteScanCacheCmd(toScan), batchScanCmd(toScan, opts))
74	}
75	
76	// scanAllUnscanned triggers batch scanning of all unscanned git repos visible in the current view.
77	func (m Model) scanAllUnscanned() (tea.Model, tea.Cmd) {
78		paths := m.collectAllRepoPaths()
79		var unscanned []string
80		for _, path := range paths {
81			if _, ok := m.scanCache[path]; !ok && !m.busy(path) {
82				unscanned = append(unscanned, path)
83			}
84		}
85		if len(unscanned) == 0 {
86			return m, nil
87		}
88		return m, batchScanCmd(unscanned, scan.OptionsFromConfig(m.config.Scan))
89	}
90	
91	// requestScanAll triggers batch scanning of all git repos visible in the current view,
92	// purging in-memory and disk cache first (Rule 126).
93	func (m Model) requestScanAll() (tea.Model, tea.Cmd) {
94		// A busy repository is left out of the purge as well as the rescan: purging
95		// it would blank its counts with nothing on the way to replace them.
96		var paths []string
97		for _, path := range m.collectAllRepoPaths() {
98			if !m.busy(path) {
99				paths = append(paths, path)
100			}
101		}
102		if len(paths) == 0 {
103			return m, nil
104		}
105		// Purge in-memory cache synchronously (Update() is thread-safe)
106		for _, path := range paths {
107			delete(m.scanCache, path)
108		}
109		return m, tea.Batch(deleteScanCacheCmd(paths), batchScanCmd(paths, scan.OptionsFromConfig(m.config.Scan)))
110	}
111	
112	// collectAllRepoPaths returns all git repo paths visible in the current view,
113	// including sub-repos nested within non-git directories.
114	func (m Model) collectAllRepoPaths() []string {
115		var paths []string
116		for _, entry := range m.entries() {
117			if entry.IsGitRepo {
118				paths = append(paths, entry.Path)
119			} else if len(entry.SubRepoPaths) > 0 {
120				paths = append(paths, entry.SubRepoPaths...)
121			}
122		}
123		return paths
124	}
125	
126	// handleWorkspaceScanComplete processes the result of a completed workspace scan (Rule 128).
127	func (m Model) handleWorkspaceScanComplete(msg WorkspaceScanCompleteMsg) (tea.Model, tea.Cmd) {
128		delete(m.scanningPaths, msg.RepoPath)
129		if msg.Error != nil {
130			log.Printf("ERROR [workspaces] scan complete %s: %v", msg.RepoPath, msg.Error)
131			m.footerError = "Scan failed — check logs"
132			m.refreshRows()
133			return m, clearFooterInfoCmd()
134		}
135		m.footerError = ""
136		m.scanCache[msg.RepoPath] = cache.WorkspaceScanEntry{
137			RepoPath:  msg.RepoPath,
138			Critical:  msg.Critical,
139			High:      msg.High,
140			Medium:    msg.Medium,
141			Low:       msg.Low,
142			Sensitive: msg.Sensitive,
143			ScannedAt: msg.ScannedAt,
144		}
145		m.refreshRows()
146		return m, nil
147	}
148	
149	// resolveTargetPath returns the path to open for terminal/IDE actions.
150	// Priority: selected directory entry > current browsed path > workspaces root.
151	func (m Model) resolveTargetPath() string {
152		targetPath := m.getExpandedWorkspacesDir()
153		if m.currentPath != "" {
154			targetPath = m.currentPath
155		}
156		if entry, ok := m.selectedEntry(); ok && entry.IsDir {
157			targetPath = entry.Path
158		}
159		return targetPath
160	}
161	
162	// launchDetachedCmd returns a Cmd that starts bin with args in a detached process
163	// and reports the result as TerminalOpenedMsg.
164	func launchDetachedCmd(bin string, args []string) tea.Cmd {
165		return func() tea.Msg {
166			cmd := exec.Command(bin, args...)
167			return TerminalOpenedMsg{Error: cmd.Start()}
168		}
169	}
170	
171	// openTerminalWindow opens a new terminal window at the target directory.
172	// Resolution order:
173	//  1. config.App.TerminalCommand override → detached process (non-blocking)
174	//  2. Auto-detect from environment → detached process (non-blocking)
175	//  3. No fallback — shows a footer error (does not work on WSL)
176	func (m Model) openTerminalWindow() (tea.Model, tea.Cmd) {
177		targetPath := m.resolveTargetPath()
178	
179		// Config override: e.g. "kitty --directory"
180		if m.config.App.TerminalCommand != "" {
181			parts := strings.Fields(m.config.App.TerminalCommand)
182			return m, launchDetachedCmd(parts[0], append(parts[1:], targetPath))
183		}
184	
185		// Auto-detect terminal from environment
186		if bin, args, ok := detectTerminalCmd(targetPath); ok {
187			return m, launchDetachedCmd(bin, args)
188		}
189	
190		// No terminal detected (common on WSL) — report to user
191		m.footerError = "No terminal detected — set App.TerminalCommand in config"
192		return m, clearFooterInfoCmd()
193	}
194	
195	// openTerminalInPlace suspends the TUI and opens a shell in the given directory.
196	func (m Model) openTerminalInPlace(targetPath string) (tea.Model, tea.Cmd) {
197		shell := detectShell()
198		if shell == "/bin/sh" {
199			if _, err := os.Stat("/bin/bash"); err == nil {
200				shell = "/bin/bash"
201			}
202		}
203		cmd := exec.Command(shell)
204		cmd.Dir = targetPath
205		return m, tea.ExecProcess(cmd, func(err error) tea.Msg {
206			if err != nil {
