327	// handleScanRequest rescans one repository by path, whoever asked.
328	//
329	// The router sends this when a cached scan's stored result has gone missing:
330	// the row is still in the list, and the scan that would replace it belongs
331	// here, next to the cache it writes. Rule 126's ctrl+s semantics — the entry is
332	// overwritten, not purged — because the result the user tried to open is
333	// precisely what is being replaced.
334	func (m Model) handleScanRequest(msg ScanRequestMsg) (tea.Model, tea.Cmd) {
335		if msg.TargetPath == "" {
336			return m, nil
337		}
338		if m.busy(msg.TargetPath) {
339			m.footerInfo = busyMessage
340			return m, clearFooterInfoCmd()
341		}
342		delete(m.scanCache, msg.TargetPath)
343		return m, tea.Batch(
344			deleteScanCacheCmd([]string{msg.TargetPath}),
345			batchScanCmd([]string{msg.TargetPath}, scan.OptionsFromConfig(m.config.Scan)),
346		)
347	}
