93	// RenderFooter returns the footer content rendered below the viewport (Rule 124).
94	func (m Model) RenderFooter(width int) string {
95		if m.mode == ModeSelecting {
96			infoLine := theme.EmptyLineBg(width)
97			if m.selectionMessage != "" {
98				infoLine = lipgloss.NewStyle().
99					Foreground(theme.ColorHighlight).
100					Background(theme.ColorBackground).
