160	// pathBaseName returns the last component of a filesystem path.
161	//
162	// It splits with filepath, not on "/". The paths here are the ones os.ReadDir
163	// and filepath.Join produced, so on Windows they are separated by backslashes —
164	// and a split on "/" alone found nothing to cut, leaving the breadcrumb reading
165	// `󰉋 C:\Users\anthoni\workspaces\anthnell  󰉋 C:\Users\anthoni\workspaces\anthnell\devsecops`
166	// instead of `󰉋 anthnell  󰉋 devsecops`. Three tabs of that overflow the line
167	// and say less than one word each would.
168	func pathBaseName(path string) string {
169		if path == "" {
170			return ""
171		}
172		return filepath.Base(path)
