231	// formatScanColumns returns the SENSITIVE, C, H, M, L, SCANNED column values for an entry.
232	// For git repos: looks up the scan cache directly.
233	// For directories: aggregates sub-repo scan entries.
234	func (m *Model) formatScanColumns(entry Entry, frame string) (sensitive secretsCell, c, h, med, l, scanned string) {
235		dash := "-"
236		empty := ""
237		none := secretsCell{}
238		unscanned := secretsCell{Text: dash}
239	
240		if entry.IsGitRepo {
241			if m.scanningPaths[entry.Path] {
242				return none, dash, dash, dash, dash, frame + " scanning"
243			}
244			scanEntry, ok := m.scanCache[entry.Path]
245			if !ok {
246				return unscanned, dash, dash, dash, dash, dash
247			}
248			return secretsFor(theme.SecretsVerdict(scanEntry.Sensitive, true)),
249				fmt.Sprintf("%d", scanEntry.Critical),
250				fmt.Sprintf("%d", scanEntry.High),
251				fmt.Sprintf("%d", scanEntry.Medium),
252				fmt.Sprintf("%d", scanEntry.Low),
253				theme.IconPending + " " + timeAgo(scanEntry.ScannedAt)
254		}
255	
256		// Files are not scannable — return empty columns
257		if !entry.IsDir {
258			return none, empty, empty, empty, empty, empty
259		}
260	
261		// Directory: aggregate sub-repos
262		if len(entry.SubRepoPaths) == 0 {
263			return secretsFor(theme.SecretsUnknown), empty, empty, empty, empty, empty
264		}
265	
266		// Count how many sub-repos are currently scanning
267		scanningCount := 0
268		for _, repoPath := range entry.SubRepoPaths {
269			if m.scanningPaths[repoPath] {
270				scanningCount++
271			}
272		}
273	
274		var scannedEntries []cache.WorkspaceScanEntry
275		for _, repoPath := range entry.SubRepoPaths {
276			if e, ok := m.scanCache[repoPath]; ok {
277				scannedEntries = append(scannedEntries, e)
278			}
279		}
280	
281		if len(scannedEntries) == 0 && scanningCount == 0 {
282			return unscanned, empty, empty, empty, empty, dash
283		}
284		if len(scannedEntries) == 0 && scanningCount > 0 {
285			return none, dash, dash, dash, dash, frame + " scanning"
286		}
287	
288		totalC, totalH, totalM, totalL := 0, 0, 0, 0
289		verdicts := make([]theme.SecretsState, 0, len(scannedEntries))
290		for _, e := range scannedEntries {
291			totalC += e.Critical
292			totalH += e.High
293			totalM += e.Medium
294			totalL += e.Low
295			verdicts = append(verdicts, theme.SecretsVerdict(e.Sensitive, true))
296		}
297	
298		scannedCount := len(scannedEntries)
299		totalCount := len(entry.SubRepoPaths)
300		scanned = theme.IconDirectory + " " + fmt.Sprintf("%d/%d", scannedCount, totalCount)
301	
302		// Le répertoire ne porte que les dépôts scannés : ceux qui ne le sont pas
303		// entrent dans le verdict par le compte ci-dessous, pas par un verdict à eux.
304		if scannedCount < totalCount {
305			verdicts = append(verdicts, theme.SecretsUnknown)
306		}
307	
308		return secretsFor(foldSecrets(verdicts)),
309			fmt.Sprintf("%d", totalC),
310			fmt.Sprintf("%d", totalH),
311			fmt.Sprintf("%d", totalM),
312			fmt.Sprintf("%d", totalL),
313			scanned
314	}
315	
316	// secretsCell is the Secrets column's two halves: what it prints, and the
317	// verdict that colours it.
318	//
319	// Les deux ne se déduisent pas l'un de l'autre. Le texte a des cas que le
320	// verdict n'a pas — un tiret pour un dépôt jamais scanné, rien du tout pour un
321	// fichier, rien non plus pendant un scan — et ces trois-là se colorent pareil,
322	// en dim, parce qu'ils disent tous « pas de verdict ».
323	type secretsCell struct {
324		Text  string
325		State theme.SecretsState
326	}
327	
328	// secretsFor is the cell of a target that has a verdict. Texte brut (Rule 122) :
329	// la couleur passe par Style.
330	func secretsFor(state theme.SecretsState) secretsCell {
331		return secretsCell{Text: theme.SecretsIcon(state), State: state}
332	}
333	
334	// foldSecrets is the verdict a directory row carries for the repositories under
335	// it. Un secret trouvé l'emporte sur tout ; un dépôt que personne n'a regardé
336	// l'emporte sur « propre », parce qu'un parent ne peut pas être plus sûr que ce
337	// qu'on ignore de ses enfants.
338	func foldSecrets(states []theme.SecretsState) theme.SecretsState {
339		out := theme.SecretsClean
340		if len(states) == 0 {
341			return theme.SecretsUnknown
342		}
343		for _, state := range states {
344			switch state {
345			case theme.SecretsFound:
346				return theme.SecretsFound
347			case theme.SecretsUnknown:
348				out = theme.SecretsUnknown
349			}
350		}
351		return out
352	}
