388				{Key: "enter", Description: "Select"},
389				{Key: "esc", Description: "Back/Cancel"},
390			}
391		}
392	
393		// Normal mode — determine selected entry state for dynamic shortcuts (Rule 130)
394		var selectedEntry *Entry
395		if entry, ok := m.selectedEntry(); ok {
396			selectedEntry = &entry
397		}
398	
399		isGitRepo := selectedEntry != nil && selectedEntry.IsGitRepo
400		var hasScanResult bool
401		if isGitRepo {
402			_, hasScanResult = m.scanCache[selectedEntry.Path]
403		}
404		hasSubRepos := selectedEntry != nil && !isGitRepo && len(selectedEntry.SubRepoPaths) > 0
405	
406		shortcuts := []shortcut.Shortcut{
407			{Key: "←→", Description: "Open/Back"},
408		}
