410		// enter: only shown for git repos with cached scan results
411		if hasScanResult {
412			shortcuts = append(shortcuts, shortcut.Shortcut{Key: "enter", Description: "Scan details"})
413		}
414	
415		shortcuts = append(shortcuts,
