423			shortcuts = append(shortcuts, shortcut.Shortcut{Key: "ctrl+w", Description: "Browser"})
424		}
425	
426		// ctrl+s and s: shown for git repos and directories with nested repos —
427		// both act on the same target, so they appear and disappear together.
428		if isGitRepo || hasSubRepos {
429			shortcuts = append(shortcuts,
430				shortcut.Shortcut{Key: "ctrl+s", Description: "Scan"},
431				shortcut.Shortcut{Key: "s", Description: "Sync"},
432			)
433		}
434	
435		shortcuts = append(shortcuts,
436			shortcut.Shortcut{Key: "A", Description: "Scan unscanned"},
437			shortcut.Shortcut{Key: "ctrl+a", Description: "Scan all"},
438		)
