440		// ctrl+n: hidden when a git repo is selected
441		if !isGitRepo {
442			shortcuts = append(shortcuts, shortcut.Shortcut{Key: "ctrl+n", Description: "New directory"})
443		}
444	
445		shortcuts = append(shortcuts,
446			shortcut.Shortcut{Key: "r", Description: "Rename"},
447			shortcut.Shortcut{Key: "ctrl+d", Description: "Delete"},
448			shortcut.Shortcut{Key: "ctrl+r", Description: "Refresh"},
