72	// or, for a frameless view, a titled rule with no corners: GetTitle() garde un
73	// lecteur là où une bordure haute dessinerait le haut d'une boîte inexistante.
74	func (a *App) renderTitleLine() string {
75		title := ""
76		if view, ok := a.views[a.currentView]; ok {
77			if hv, implements := view.(HeaderView); implements {
78				title = hv.GetTitle()
79			}
80		}
81		if a.frameless() {
82			return theme.RenderTitledRule(title, a.width)
83		}
84		return theme.RenderBorderTitle(title, a.width)
85	}
