input.content:
// Package viewer parses a document into something a read-only pane can show:
// a tree for JSON and XML, levelled lines for a log, plain text for the rest.
//
// It knows nothing about Bubble Tea, lipgloss or the theme. What a token or a
// level is *coloured* is decided in internal/ui/viewer; what one *is* is decided
// here.
package viewer

// Kind is what a document turned out to be.
type Kind string

const (
	// KindAuto asks Open to decide from the name and, failing that, the content.
	// It is what a producer passes when it does not know — a file browser.
	KindAuto  Kind = ""
	KindPlain Kind = "plain"
	KindJSON  Kind = "json"
	KindXML   Kind = "xml"
	KindLog   Kind = "log"
)

// Structured reports whether the kind has a tree to walk. It is the one question
// the view asks before offering the tree display, so it is answered here rather
// than by a switch written out at each call site.
func (k Kind) Structured() bool {
	return k == KindJSON || k == KindXML
}

// String is the kind as the header prints it.
func (k Kind) String() string {
	if k == KindAuto {
		return string(KindPlain)
	}
	return string(k)
}

// Document is a parsed document, ready to be displayed.
//
// Kind is what it *turned out* to be, which is not always what was asked for: a
// malformed JSON is a plain document that remembers why (ParseErr). Refusing to
// open it would hide exactly the content needed to fix it.
type Document struct {
	Name string
	Kind Kind

	// Text is the normalized content: no ANSI escapes, no carriage returns.
	// Every display reads it, the tree included — the tree is a second view of
	// this, never a replacement for it.
	Text string

	// Root is the parsed tree, for a structured kind only.
	Root *Node

	// Lines carries a level per line, for KindLog only.
	Lines []LogLine

	// ParseErr is set when a kind the *name* declared failed to parse. A kind
	// merely sniffed from the content never sets it: a Markdown file opening
	// with a tag is not a broken XML document, and saying so would be noise.
	ParseErr error
}

// Open parses data into a Document.
//
// kind is what the producer declares — `docker logs` is a log whatever it looks
// like — or KindAuto to let the name and the content decide.
func Open(name string, kind Kind, data []byte) Document {
	doc := Document{Name: name, Text: Normalize(data)}

	declared := kind != KindAuto
	if !declared {
		det := detect(name, data)
		kind, declared = det.Kind, det.Declared
	}
	doc.Kind = kind

	switch kind {
	case KindJSON:
		root, err := parseJSON(doc.Text)
		if err != nil {
			return doc.fallBackToText(err, declared)
		}
		doc.Root = root

	case KindXML:
		root, err := parseXML(doc.Text)
		if err != nil {
			return doc.fallBackToText(err, declared)
		}
		doc.Root = root

	case KindLog:
		doc.Lines = ParseLog(doc.Text)
	}

	return doc
}

// fallBackToText turns a document that would not parse into a plain one, and
// keeps the reason only when it is worth telling the user about.
func (d Document) fallBackToText(err error, declared bool) Document {
	d.Kind = KindPlain
	d.Root = nil
	if declared {
		d.ParseErr = err
	}
	return d
}

// NodeCount is what the header shows for a structured document.
func (d Document) NodeCount() int {
	return countNodes(d.Root)
}

func countNodes(n *Node) int {
	if n == nil {
		return 0
	}
	total := 1
	for _, child := range n.Children {
		total += countNodes(child)
	}
	return total
}

package viewer

// NodeKind is what a tree node holds. JSON and XML share the type because the
// tree that walks them is one component; the kinds themselves do not overlap.
type NodeKind string

const (
	// JSON
	NodeObject NodeKind = "object"
	NodeArray  NodeKind = "array"
	NodeString NodeKind = "string"
	NodeNumber NodeKind = "number"
	NodeBool   NodeKind = "bool"
	NodeNull   NodeKind = "null"

	// XML
	NodeElement NodeKind = "element"
	NodeAttr    NodeKind = "attr"
	NodeText    NodeKind = "text"
	NodeComment NodeKind = "comment"
)

// Node is one entry in the tree.
//
// ID identifies it, and it is an int assigned in document order rather than a
// path like `$.spec.containers[0].name`. The tree is parsed once when the
// document opens and never re-parsed, so the counter is stable for as long as
// anything refers to it — and the view's expansion set is a map[int]bool with
// nothing to keep in step. A path would be a second representation of the same
// identity, with more ways for the two to disagree.
type Node struct {
	ID       int
	Key      string
	Value    string
	Kind     NodeKind
	Children []*Node
}

// HasChildren drives the expand chevron. An empty object is a container with
// nothing to expand into, and offering a chevron for it would promise a level
// that is not there.
func (n *Node) HasChildren() bool {
	return n != nil && len(n.Children) > 0
}

// FlatNode is a node at the depth it renders at.
type FlatNode struct {
	Node  *Node
	Depth int
}

// Flatten returns the rows visible for a given set of collapsed nodes, in
// document order.
//
// It is here rather than in the view because it is pure: a tree and a set in,
// a slice out. The set itself is the view's, because being collapsed is a fact
// about the screen and not about the document.
func Flatten(root *Node, collapsed map[int]bool) []FlatNode {
	if root == nil {
		return nil
	}
	var out []FlatNode
	var walk func(n *Node, depth int)
	walk = func(n *Node, depth int) {
		out = append(out, FlatNode{Node: n, Depth: depth})
		if collapsed[n.ID] {
			return
		}
		for _, child := range n.Children {
			walk(child, depth+1)
		}
	}
	walk(root, 0)
	return out
}

// idGen hands out node identities during a parse. It is a type rather than a
// bare *int so the two parsers cannot disagree about whether it pre- or
// post-increments.
type idGen struct{ next int }

func (g *idGen) take() int {
	id := g.next
	g.next++
	return id
}

package viewer

import (
	"strings"

	"github.com/charmbracelet/x/ansi"
)

// Normalize turns raw bytes into text a viewport can hold.
//
// Both steps are needed, and the reasons come from the container logs pane this
// was moved out of: systemd and anything using a logging library emit coloured
// output, and some containers use \r to overwrite a progress bar in place.
// Either one corrupts the frame — an escape sequence is measured as its bytes
// rather than its width, and a carriage return sends the cursor back over
// content Bubble Tea believes it has drawn.
//
// It runs for *every* document, not just logs. A file can contain the same
// bytes, and a viewer that renders it faithfully renders it broken.
//
// The cost is stated rather than hidden: a JSON string holding a literal escape
// character loses it. That is a trade against a corrupted frame, and the frame
// wins.
func Normalize(data []byte) string {
	text := ansi.Strip(string(data))
	text = strings.ReplaceAll(text, "\r\n", "\n")
	return strings.ReplaceAll(text, "\r", "")
}

package viewer

import "strings"

// WrapLines soft-wraps content so no line exceeds width runes.
//
// It breaks at the width and not at a word boundary, deliberately. The content
// here is a log line, a stack trace or a minified document, where the columns
// carry meaning and a word-wrap would shuffle them; a paragraph of prose is not
// what this pane is for.
func WrapLines(content string, width int) string {
	if width <= 0 {
		return content
	}
	lines := strings.Split(content, "\n")
	out := make([]string, 0, len(lines))
	for _, line := range lines {
		runes := []rune(line)
		if len(runes) <= width {
			out = append(out, line)
			continue
		}
		for len(runes) > width {
			out = append(out, string(runes[:width]))
			runes = runes[width:]
		}
		if len(runes) > 0 {
			out = append(out, string(runes))
		}
	}
	return strings.Join(out, "\n")
}

package viewer

import (
	"bytes"
	"errors"
	"fmt"
	"os"
)

// MaxSize is the largest file the viewer will open. Everything above it is
// refused by name rather than loaded and then survived.
const MaxSize = 5 << 20 // 5 MiB

// sniffSize is how much of a file decides whether it is text.
const sniffSize = 8 << 10

// ErrTooLarge and ErrBinary are the two refusals. They are values rather than
// formatted strings so the caller can report them without matching on prose.
var (
	ErrTooLarge = errors.New("file is too large to view")
	ErrBinary   = errors.New("not a text file")
)

// ReadFile loads a file for the viewer, refusing the two things it cannot show.
//
// The cap is a *file* concern and lives here rather than in a producer: a
// source that fetches — `docker logs --tail 500` — is bounded by its own
// command, and applying a byte ceiling to it would be answering a question
// nobody asked.
func ReadFile(path string) ([]byte, error) {
	info, err := os.Stat(path)
	if err != nil {
		return nil, err
	}
	if info.IsDir() {
		return nil, fmt.Errorf("%s is a directory", path)
	}
	if info.Size() > MaxSize {
		return nil, ErrTooLarge
	}

	data, err := os.ReadFile(path)
	if err != nil {
		return nil, err
	}
	if IsBinary(data) {
		return nil, ErrBinary
	}
	return data, nil
}

// IsBinary reports whether data looks like something a text pane must not try
// to render.
//
// Two signals, and the first one catches nearly everything: a NUL byte, which
// no text encoding this application will meet uses, and which every executable,
// archive and image carries early. The second is a density of other control
// bytes, for the formats that manage to avoid NUL in their first pages.
func IsBinary(data []byte) bool {
	head := data
	if len(head) > sniffSize {
		head = head[:sniffSize]
	}
	if len(head) == 0 {
		return false
	}
	if bytes.IndexByte(head, 0) >= 0 {
		return true
	}

	control := 0
	for _, b := range head {
		if b < 0x20 && b != '\n' && b != '\t' && b != '\r' && b != 0x1b {
			control++
		}
	}
	return control*100/len(head) > 30
}

package viewer

import (
	"path/filepath"
	"strings"
)

// detection is what the name and the content managed to say about a document.
//
// Declared separates "the name said JSON" from "the content started with a
// brace". Only the first is worth reporting a parse failure for: a Markdown
// file that happens to open with a tag is not a broken XML document, and
// telling the user it is would be noise about a file that is displaying fine.
type detection struct {
	Kind     Kind
	Declared bool
}

// extensionKinds are the extensions that decide, on their own, what a file is.
//
// A log is only ever recognised here or declared by its producer — never
// sniffed from the content. "This looks like a log" is not a decidable
// question, and the registry `provider` field is the precedent: declared, never
// inferred from the URL, so nothing depends on what happened to be seen first.
var extensionKinds = map[string]Kind{
	".json": KindJSON,
	".xml":  KindXML,
	".log":  KindLog,
}

// DetectKind is what a document is, judged by its name and then its content.
func DetectKind(name string, data []byte) Kind {
	return detect(name, data).Kind
}

func detect(name string, data []byte) detection {
	ext := strings.ToLower(filepath.Ext(name))
	if kind, ok := extensionKinds[ext]; ok {
		return detection{Kind: kind, Declared: true}
	}
	// Any other extension is taken at its word: a .md, a .go or a .txt is text,
	// and sniffing it would open a Markdown file as a tree the first time
	// someone started one with a tag.
	if ext != "" {
		return detection{Kind: KindPlain}
	}
	return detection{Kind: sniff(data)}
}

// sniff guesses at a file with no extension at all — a Dockerfile, a Makefile,
// a dump someone redirected into a name. It looks at the first meaningful byte
// and nothing else; a document that then fails to parse simply falls back to
// text, with no complaint, because nothing claimed it was structured.
func sniff(data []byte) Kind {
	head := data
	if len(head) > sniffSize {
		head = head[:sniffSize]
	}
	trimmed := strings.TrimLeft(string(head), " \t\r\n﻿")
	switch {
	case strings.HasPrefix(trimmed, "{"), strings.HasPrefix(trimmed, "["):
		return KindJSON
	case strings.HasPrefix(trimmed, "<"):
		return KindXML
	default:
		return KindPlain
	}
}

package viewer

import (
	"regexp"
	"strings"
)

// Level is a log line's severity, ordered so a filter can be a single
// comparison.
//
// LevelUnknown is zero and is *not* the bottom of the scale — it means nobody
// could tell. Passes treats it separately for that reason.
type Level int

const (
	LevelUnknown Level = iota
	LevelTrace
	LevelDebug
	LevelInfo
	LevelWarn
	LevelError
)

// Levels are the filter's positions, ascending. LevelUnknown is absent: it is
// not a level a user can filter to, it is the absence of one.
var Levels = []Level{LevelTrace, LevelDebug, LevelInfo, LevelWarn, LevelError}

func (l Level) String() string {
	switch l {
	case LevelTrace:
		return "trace"
	case LevelDebug:
		return "debug"
	case LevelInfo:
		return "info"
	case LevelWarn:
		return "warn"
	case LevelError:
		return "error"
	default:
		return "unknown"
	}
}

// Passes reports whether a line survives a minimum-level filter.
//
// An unlevelled line always passes, and that is the whole point of the filter
// being usable: a stack trace is a dozen lines with no level on any of them,
// and a filter that swallowed them would destroy exactly what the user opened
// the log to read. Inheritance (see ParseLog) covers the lines that belong to
// an entry above them; this covers the ones that belong to nothing.
func (l Level) Passes(min Level) bool {
	return l == LevelUnknown || min == LevelUnknown || l >= min
}

// LogLine is one line and what could be worked out about it.
type LogLine struct {
	Text  string
	Level Level
}

// ParseLog splits text into levelled lines.
//
// A line with no level of its own inherits the effective level of the line
// above it. That is what makes a stack trace survive a filter set to its
// parent's level, and it chains: twenty continuation lines all carry the level
// of the entry that started them.
//
// The trade is real and stated here rather than discovered later: a genuinely
// unrelated line with no level, following an INFO, is filtered out with it.
// Losing a stray line beats losing a stack trace, and it is where lnav and
// stern landed too.
func ParseLog(text string) []LogLine {
	raw := strings.Split(text, "\n")
	lines := make([]LogLine, 0, len(raw))

	inherited := LevelUnknown
	for _, line := range raw {
		level := detectLevel(line)
		if level == LevelUnknown {
			// Blank lines break the chain: they are the one thing that reliably
			// separates one entry from the next, and letting a level carry
			// across them would colour half a file from a single ERROR.
			if strings.TrimSpace(line) == "" {
				inherited = LevelUnknown
			}
			level = inherited
		} else {
			inherited = level
		}
		lines = append(lines, LogLine{Text: line, Level: level})
	}
	return lines
}

// Three shapes, because a container's log is as likely to be any of them. They
// are tried in order of how certain they are: a structured field means what it
// says, a bare word in a line is a guess.
var (
	jsonLevelRe   = regexp.MustCompile(`"(?:level|severity|lvl)"\s*:\s*"([A-Za-z]+)"`)
	logfmtLevelRe = regexp.MustCompile(`(?i)\b(?:level|lvl|severity)=("?)([A-Za-z]+)\1`)

	// Uppercase only, and only as a standalone token. A lowercase "error" is a
	// word people write in sentences; an uppercase one, delimited, is a field.
	// Refusing lowercase here costs a few applications their colour and saves
	// every line that merely mentions the word from being filtered as one.
	bareLevelRe = regexp.MustCompile(`(?:^|[\s\[(|])(FATAL|PANIC|ERROR|ERRO|ERR|WARNING|WARN|WRN|NOTICE|INFO|INF|DEBUG|DEBU|DBG|TRACE|TRC)(?:[\s\])|:=]|$)`)
)

// bareLevelWindow is how far into a line a bare level token is still credible.
// Past a timestamp, a hostname and a logger name, a word in the message body is
// prose.
const bareLevelWindow = 64

func detectLevel(line string) Level {
	if m := jsonLevelRe.FindStringSubmatch(line); m != nil {
		if level, ok := ParseLevel(m[1]); ok {
			return level
		}
	}
	if m := logfmtLevelRe.FindStringSubmatch(line); m != nil {
		if level, ok := ParseLevel(m[2]); ok {
			return level
		}
	}

	head := line
	if len(head) > bareLevelWindow {
		head = head[:bareLevelWindow]
	}
	if m := bareLevelRe.FindStringSubmatch(head); m != nil {
		if level, ok := ParseLevel(m[1]); ok {
			return level
		}
	}
	return LevelUnknown
}

// levelWords maps every spelling to its level. Fatal and panic fold into error:
// the filter asks "how bad", and a process dying is not less bad than an error.
var levelWords = map[string]Level{
	"fatal":   LevelError,
	"panic":   LevelError,
	"error":   LevelError,
	"erro":    LevelError,
	"err":     LevelError,
	"warning": LevelWarn,
	"warn":    LevelWarn,
	"wrn":     LevelWarn,
	"notice":  LevelInfo,
	"info":    LevelInfo,
	"inf":     LevelInfo,
	"debug":   LevelDebug,
	"debu":    LevelDebug,
	"dbg":     LevelDebug,
	"trace":   LevelTrace,
	"trc":     LevelTrace,
}

// ParseLevel resolves a spelling to a level. The bool separates "not a level"
// from "the zero level", which a bare Level return could not.
func ParseLevel(word string) (Level, bool) {
	level, ok := levelWords[strings.ToLower(word)]
	return level, ok
}

