package viewer

import (
	"path/filepath"
	"strings"
)

// detection is what the name and the content managed to say about a document.
//
// Declared separates "the name said JSON" from "the content started with a
// brace". Only the first is worth reporting a parse failure for: a Markdown
// file that happens to open with a tag is not a broken XML document, and
// telling the user it is would be noise about a file that is displaying fine.
type detection struct {
	Kind     Kind
	Declared bool
}

// extensionKinds are the extensions that decide, on their own, what a file is.
//
// A log is only ever recognised here or declared by its producer — never
// sniffed from the content. "This looks like a log" is not a decidable
// question, and the registry `provider` field is the precedent: declared, never
// inferred from the URL, so nothing depends on what happened to be seen first.
var extensionKinds = map[string]Kind{
	".json": KindJSON,
	".xml":  KindXML,
	".log":  KindLog,
}

// DetectKind is what a document is, judged by its name and then its content.
func DetectKind(name string, data []byte) Kind {
	return detect(name, data).Kind
}

func detect(name string, data []byte) detection {
	ext := strings.ToLower(filepath.Ext(name))
	if kind, ok := extensionKinds[ext]; ok {
		return detection{Kind: kind, Declared: true}
	}
	// Any other extension is taken at its word: a .md, a .go or a .txt is text,
	// and sniffing it would open a Markdown file as a tree the first time
	// someone started one with a tag.
	if ext != "" {
		return detection{Kind: KindPlain}
	}
	return detection{Kind: sniff(data)}
}

// leadingNoise is what may sit in front of a document's first real character:
// whitespace, and a byte-order mark an editor left behind. Without the mark in
// this set, a BOM would hide the very byte this function exists to read.
const leadingNoise = " \t\r\n﻿"

// sniff guesses at a file with no extension at all — a Dockerfile, a Makefile,
// a dump someone redirected into a name. It looks at the first meaningful byte
// and nothing else; a document that then fails to parse simply falls back to
// text, with no complaint, because nothing claimed it was structured.
func sniff(data []byte) Kind {
	head := data
	if len(head) > sniffSize {
		head = head[:sniffSize]
	}
	trimmed := strings.TrimLeft(string(head), leadingNoise)
	switch {
	case strings.HasPrefix(trimmed, "{"), strings.HasPrefix(trimmed, "["):
		return KindJSON
	case strings.HasPrefix(trimmed, "<"):
		return KindXML
	default:
		return KindPlain
	}
}

package viewer

import (
	"encoding/json"
	"errors"
	"fmt"
	"io"
	"strings"
)

// parseJSON builds the tree from a token stream rather than from a decoded
// value.
//
// The reason is the one thing a JSON viewer must not get wrong: order.
// Unmarshalling into map[string]any loses the order the file was written in,
// and a configuration read back with its keys alphabetised is a different
// document to the one on disk. json.Decoder.Token() hands them over in the
// order they appear, which is also why the tree cannot be sorted afterwards
// (the columns declare no comparator).
func parseJSON(text string) (*Node, error) {
	dec := json.NewDecoder(strings.NewReader(text))
	dec.UseNumber() // a float64 round-trip would rewrite 1e9 and lose precision

	ids := &idGen{}
	root, err := parseJSONValue(dec, "", ids)
	if err != nil {
		return nil, err
	}

	// A second value after the first is not a JSON document. Without this, a
	// file holding `{"a":1} garbage` would open as a tree showing only the part
	// that happened to parse.
	if _, err := dec.Token(); !errors.Is(err, io.EOF) {
		return nil, fmt.Errorf("trailing content after the top-level value")
	}
	return root, nil
}

func parseJSONValue(dec *json.Decoder, key string, ids *idGen) (*Node, error) {
	token, err := dec.Token()
	if err != nil {
		return nil, err
	}
	return parseJSONToken(dec, token, key, ids)
}

func parseJSONToken(dec *json.Decoder, token json.Token, key string, ids *idGen) (*Node, error) {
	node := &Node{ID: ids.take(), Key: key}

	switch t := token.(type) {
	case json.Delim:
		switch t {
		case '{':
			node.Kind = NodeObject
			if err := parseJSONObject(dec, node, ids); err != nil {
				return nil, err
			}
			node.Value = fmt.Sprintf("{%d}", len(node.Children))
		case '[':
			node.Kind = NodeArray
			if err := parseJSONArray(dec, node, ids); err != nil {
				return nil, err
			}
			node.Value = fmt.Sprintf("[%d]", len(node.Children))
		default:
			return nil, fmt.Errorf("unexpected %q", t)
		}

	case string:
		node.Kind = NodeString
		node.Value = quoteInline(t)

	case json.Number:
		node.Kind = NodeNumber
		node.Value = t.String()

	case bool:
		node.Kind = NodeBool
		node.Value = fmt.Sprintf("%t", t)

	case nil:
		node.Kind = NodeNull
		node.Value = "null"

	default:
		return nil, fmt.Errorf("unsupported token %T", token)
	}

	return node, nil
}

func parseJSONObject(dec *json.Decoder, parent *Node, ids *idGen) error {
	for dec.More() {
		keyToken, err := dec.Token()
		if err != nil {
			return err
		}
		key, ok := keyToken.(string)
		if !ok {
			return fmt.Errorf("object key is %T, not a string", keyToken)
		}
		child, err := parseJSONValue(dec, key, ids)
		if err != nil {
			return err
		}
		parent.Children = append(parent.Children, child)
	}
	_, err := dec.Token() // the closing brace
	return err
}

func parseJSONArray(dec *json.Decoder, parent *Node, ids *idGen) error {
	for index := 0; dec.More(); index++ {
		child, err := parseJSONValue(dec, fmt.Sprintf("[%d]", index), ids)
		if err != nil {
			return err
		}
		parent.Children = append(parent.Children, child)
	}
	_, err := dec.Token() // the closing bracket
	return err
}

// quoteInline renders a string value as one row's worth of text.
//
// The quotes stay: without them a string "42" and the number 42 read
// identically, and colour alone should not have to carry that. The escapes
// matter more — an unescaped newline inside a value would end the row halfway
// and push every column after it onto a line of its own.
func quoteInline(s string) string {
	replacer := strings.NewReplacer(
		"\\", `\\`,
		"\"", `\"`,
		"\n", `\n`,
		"\t", `\t`,
	)
	return `"` + replacer.Replace(s) + `"`
}

package viewer

import (
	"encoding/xml"
	"errors"
	"fmt"
	"io"
	"strings"
)

// parseXML builds the tree from the token stream, for the same reason as the
// JSON parser: order is content.
//
// Two shaping decisions, both about what a reader wants to see rather than what
// the format technically holds:
//
//   - An attribute is a node of its own, a child of its element. Most XML worth
//     reading keeps its information in attributes, and a tree that showed only
//     elements would show almost nothing.
//   - An element whose only content is text carries that text as its own value
//     instead of gaining a child for it. It halves the depth of every document
//     that is mostly leaves, and `<name>nginx</name>` reads as one row because
//     it is one fact.
func parseXML(text string) (*Node, error) {
	dec := xml.NewDecoder(strings.NewReader(text))
	ids := &idGen{}

	var root *Node
	var stack []*Node
	// texts holds the character data seen so far for each open element, keyed by
	// its depth in the stack. It is resolved at EndElement, which is the first
	// moment we know whether the element also had element children.
	var texts []string

	for {
		token, err := dec.Token()
		if errors.Is(err, io.EOF) {
			break
		}
		if err != nil {
			return nil, err
		}

		switch t := token.(type) {
		case xml.StartElement:
			node := &Node{ID: ids.take(), Key: elementName(t.Name), Kind: NodeElement}
			for _, attr := range t.Attr {
				node.Children = append(node.Children, &Node{
					ID:    ids.take(),
					Key:   "@" + elementName(attr.Name),
					Value: quoteInline(attr.Value),
					Kind:  NodeAttr,
				})
			}
			if len(stack) == 0 {
				if root != nil {
					return nil, fmt.Errorf("a second root element %q", node.Key)
				}
				root = node
			} else {
				parent := stack[len(stack)-1]
				parent.Children = append(parent.Children, node)
			}
			stack = append(stack, node)
			texts = append(texts, "")

		case xml.CharData:
			if len(stack) == 0 {
				continue
			}
			if trimmed := strings.TrimSpace(string(t)); trimmed != "" {
				texts[len(texts)-1] += trimmed
			}

		case xml.Comment:
			if len(stack) == 0 {
				continue
			}
			parent := stack[len(stack)-1]
			parent.Children = append(parent.Children, &Node{
				ID:    ids.take(),
				Key:   "<!--",
				Value: strings.TrimSpace(string(t)),
				Kind:  NodeComment,
			})

		case xml.EndElement:
			if len(stack) == 0 {
				return nil, fmt.Errorf("closing tag %q with nothing open", t.Name.Local)
			}
			node := stack[len(stack)-1]
			closeElement(node, texts[len(texts)-1], ids)
			stack = stack[:len(stack)-1]
			texts = texts[:len(texts)-1]
		}
	}

	if root == nil {
		return nil, fmt.Errorf("no root element")
	}
	if len(stack) != 0 {
		return nil, fmt.Errorf("%d unclosed element(s)", len(stack))
	}
	return root, nil
}

// closeElement settles what an element does with the text it collected: it
// becomes the element's own value when there is nothing else to confuse it
// with, and a child otherwise — mixed content is rare, and a row of its own is
// the only honest place for it.
func closeElement(node *Node, text string, ids *idGen) {
	if text == "" {
		return
	}
	if !hasElementChild(node) {
		node.Value = quoteInline(text)
		return
	}
	node.Children = append(node.Children, &Node{
		ID:    ids.take(),
		Key:   "#text",
		Value: quoteInline(text),
		Kind:  NodeText,
	})
}

func hasElementChild(node *Node) bool {
	for _, child := range node.Children {
		if child.Kind == NodeElement {
			return true
		}
	}
	return false
}

// elementName keeps the namespace prefix out of the tree. xml.Decoder resolves
// a prefix to the full namespace URI, so `k8s:name` would render as
// `http://…/v1 name` — a URL in every row, saying the same thing in all of them.
func elementName(name xml.Name) string {
	return name.Local
}

