package viewer

import (
	"github.com/alecthomas/chroma/v2"
	"github.com/alecthomas/chroma/v2/lexers"
)

// TokenClass is what a run of text is, for colouring purposes. It is a small
// closed set of this package's own rather than chroma's several hundred token
// types: the theme has to have an opinion about every one of them, and eight is
// a number a palette can carry.
type TokenClass int

const (
	ClassText TokenClass = iota
	ClassKey
	ClassString
	ClassNumber
	ClassLiteral // true, false, null
	ClassPunct
	ClassTag
	ClassAttr
	ClassComment
)

// Token is a run of text and what it is.
type Token struct {
	Class TokenClass
	Text  string
}

// Tokenize splits text for highlighting.
//
// chroma is used as a **lexer and nothing else**. Its formatters write their own
// ANSI colour and reset sequences, and a reset inside a line ends the app
// background for everything after it on that line (Rule 115) — the terminal's
// own background then shows through to the right margin. Emitting classes and
// letting lipgloss paint them is what keeps the background under our control.
//
// The invariant every caller depends on: concatenating the tokens' text
// reproduces the input exactly. A lexer that dropped or added a byte would
// desynchronise the rendered lines from the document's real ones.
func Tokenize(kind Kind, text string) []Token {
	name := lexerName(kind)
	if name == "" {
		return []Token{{Class: ClassText, Text: text}}
	}
	lexer := lexers.Get(name)
	if lexer == nil {
		return []Token{{Class: ClassText, Text: text}}
	}
	iterator, err := lexer.Tokenise(nil, text)
	if err != nil {
		// A lexer that will not run is not worth a message: the document is
		// displayed uncoloured, which is what `c` would have done anyway.
		return []Token{{Class: ClassText, Text: text}}
	}

	raw := iterator.Tokens()
	out := make([]Token, 0, len(raw))
	for _, token := range raw {
		out = append(out, Token{Class: classOf(kind, token.Type), Text: token.Value})
	}
	return out
}

// lexerName is the chroma lexer for a kind, or "" for a kind that has none.
//
// A log has none deliberately: its colour comes from its level, one whole line
// at a time, which is a different question from what a token is.
func lexerName(kind Kind) string {
	switch kind {
	case KindJSON:
		return "json"
	case KindXML:
		return "xml"
	default:
		return ""
	}
}

// classOf maps a chroma token type onto our palette.
//
// The mapping was read off the two lexers rather than guessed: chroma emits
// NameTag for a JSON object key *and* for an XML tag, which is why the kind is
// a parameter. Both happen to resolve to the same colour today; naming them
// apart is what lets a theme separate them later without this function being
// wrong in the meantime.
func classOf(kind Kind, t chroma.TokenType) TokenClass {
	switch t.Category() {
	case chroma.Comment:
		return ClassComment
	case chroma.Keyword:
		return ClassLiteral
	case chroma.Punctuation, chroma.Operator:
		return ClassPunct
	case chroma.Literal:
		if t.InSubCategory(chroma.LiteralNumber) {
			return ClassNumber
		}
		return ClassString
	case chroma.Name:
		switch t {
		case chroma.NameAttribute:
			return ClassAttr
		case chroma.NameTag:
			if kind == KindXML {
				return ClassTag
			}
			return ClassKey
		default:
			return ClassText
		}
	default:
		return ClassText
	}
}

package viewer

import (
	"os/exec"
	"path/filepath"
)

// Source is where a document came from, and it is carried rather than the bytes
// alone.
//
// The reason is everything the container logs pane could do that a byte slice
// cannot: reload, follow, re-fetch with timestamps. Those are properties of the
// *origin*, not of the pane — and a file gains from it too, since a document
// re-read after an external edit is the same question as a log re-fetched.
type Source interface {
	// Name is what the header shows.
	Name() string
	// Kind is what the producer declares. KindAuto lets the name and the
	// content decide, which is what a file browser passes.
	Kind() Kind
	// Load fetches the content. It runs on a Cmd's goroutine, never in Update
	// (Rule 110).
	Load() ([]byte, error)
}

// The three optional capabilities below are probed with a type assertion, the
// same way the router probes FooterView and FramelessView.
//
// Each is a *single* method on purpose. CLAUDE.md's warning about HeaderView is
// that a view supplying two of its four methods satisfies none of it and fails
// in silence; an interface with one method has no half-satisfied state to fall
// into. That is why these are three interfaces and not one with three methods.

// Timestamped is a source that can re-fetch with or without timestamps. It
// unlocks `t`.
type Timestamped interface {
	Source
	WithTimestamps(on bool) Source
}

// Followable is a source that can stream live output. It unlocks `ctrl+f`.
//
// It returns a command rather than a stream because following suspends the TUI
// and hands the terminal over (tea.ExecProcess): a viewport that tried to tail
// a stream would be re-implementing `less +F` badly.
type Followable interface {
	Source
	FollowCmd() *exec.Cmd
}

// Pageable is a source that can be handed to the system pager. It unlocks `e`.
//
// It survives for logs alone, and deliberately: `less` handles a gigabyte and
// follows it, which a viewport holding the whole document in memory will never
// do. Every other pager path in the application is deleted by this view.
type Pageable interface {
	Source
	PagerCmd() *exec.Cmd
}

// FileSource reads a file from disk. It is the workspaces view's source, and
// the only one in this package: the others know docker, and this package must
// not.
type FileSource struct {
	Path string
}

// NewFileSource builds a source for a path on disk.
func NewFileSource(path string) FileSource {
	return FileSource{Path: path}
}

func (s FileSource) Name() string { return filepath.Base(s.Path) }

// Kind is KindAuto: a file browser does not know what it is opening, so the
// extension and then the content decide.
func (s FileSource) Kind() Kind { return KindAuto }

func (s FileSource) Load() ([]byte, error) { return ReadFile(s.Path) }

package viewer

import (
	"strings"
	"testing"
)

// Order is the one thing a JSON viewer must not get wrong. Unmarshalling into a
// map would answer this test alphabetically, which is a different document to
// the one on disk.
func TestAJSONObjectKeepsTheOrderTheFileGaveIt(t *testing.T) {
	doc := Open("k.json", KindAuto, []byte(`{"zebra":1,"apple":2,"mango":3}`))
	if doc.Kind != KindJSON {
		t.Fatalf("Kind = %q, want json (ParseErr=%v)", doc.Kind, doc.ParseErr)
	}

	var keys []string
	for _, child := range doc.Root.Children {
		keys = append(keys, child.Key)
	}
	want := []string{"zebra", "apple", "mango"}
	if strings.Join(keys, ",") != strings.Join(want, ",") {
		t.Errorf("keys = %v, want %v — the file's order, not a sorted one", keys, want)
	}
}

func TestAJSONArrayIndexesItsChildren(t *testing.T) {
	doc := Open("a.json", KindAuto, []byte(`[10,20]`))
	if doc.Root.Kind != NodeArray {
		t.Fatalf("root kind = %q, want array", doc.Root.Kind)
	}
	if got := doc.Root.Children[1].Key; got != "[1]" {
		t.Errorf("second child key = %q, want [1]", got)
	}
	if got := doc.Root.Value; got != "[2]" {
		t.Errorf("collapsed array reads %q, want [2] — a count is what a closed container has to say", got)
	}
}

// A value that will not parse is not a reason to refuse the file: it is exactly
// the file the user needs to look at.
func TestAMalformedJSONOpensAsTextAndSaysSo(t *testing.T) {
	doc := Open("broken.json", KindAuto, []byte(`{"a": 1,}`))

	if doc.Kind != KindPlain {
		t.Errorf("Kind = %q, want plain — a broken document still displays", doc.Kind)
	}
	if doc.ParseErr == nil {
		t.Error("ParseErr is nil; the name declared JSON, so the failure is worth reporting")
	}
	if !strings.Contains(doc.Text, `"a": 1`) {
		t.Errorf("Text = %q, want the original content", doc.Text)
	}
}

// The other half of the same rule: nothing *claimed* this was structured, so a
// failed guess must be silent. A Markdown file opening with a tag is not a
// broken XML document.
func TestASniffedKindThatFailsToParseReportsNothing(t *testing.T) {
	doc := Open("Dockerfile", KindAuto, []byte("<not really xml"))

	if doc.Kind != KindPlain {
		t.Errorf("Kind = %q, want plain", doc.Kind)
	}
	if doc.ParseErr != nil {
		t.Errorf("ParseErr = %v, want nil — the content was guessed at, not declared", doc.ParseErr)
	}
}

// A producer that knows what it fetched outranks both the name and the content.
func TestADeclaredKindIsNotSecondGuessed(t *testing.T) {
	doc := Open("inspect", KindJSON, []byte(`{"Id":"abc"}`))
	if doc.Kind != KindJSON {
		t.Fatalf("Kind = %q, want json", doc.Kind)
	}

	// And a log stays a log even when its first line looks like JSON.
	logDoc := Open("logs", KindLog, []byte(`{"level":"warn","msg":"hi"}`))
	if logDoc.Kind != KindLog {
		t.Errorf("Kind = %q, want log — the producer declared it", logDoc.Kind)
	}
	if len(logDoc.Lines) != 1 || logDoc.Lines[0].Level != LevelWarn {
		t.Errorf("lines = %+v, want one warn line", logDoc.Lines)
	}
}

func TestTrailingContentIsNotAValidDocument(t *testing.T) {
	doc := Open("x.json", KindAuto, []byte(`{"a":1} and then some junk`))
	if doc.Kind != KindPlain {
		t.Errorf("Kind = %q, want plain — half a document is not a document", doc.Kind)
	}
}

func TestNormalizationStripsANSIAndCarriageReturns(t *testing.T) {
	raw := []byte("\x1b[31mred\x1b[0m\r\nsecond\rthird\n")
	got := Normalize(raw)
	want := "red\nsecondthird\n"
	if got != want {
		t.Errorf("Normalize = %q, want %q", got, want)
	}
}

func TestNodeCountCountsTheWholeTree(t *testing.T) {
	doc := Open("n.json", KindAuto, []byte(`{"a":{"b":1},"c":2}`))
	// root + a + a.b + c
	if got := doc.NodeCount(); got != 4 {
		t.Errorf("NodeCount = %d, want 4", got)
	}
}

package viewer

import "testing"

const podXML = `<?xml version="1.0"?>
<pod name="web" replicas="3">
  <!-- the front end -->
  <image>nginx:latest</image>
  <ports>
    <port protocol="tcp">8080</port>
  </ports>
</pod>`

func TestXMLAttributesAreNodesOfTheirOwn(t *testing.T) {
	doc := Open("pod.xml", KindAuto, []byte(podXML))
	if doc.Kind != KindXML {
		t.Fatalf("Kind = %q, want xml (ParseErr=%v)", doc.Kind, doc.ParseErr)
	}

	root := doc.Root
	if root.Key != "pod" {
		t.Fatalf("root = %q, want pod", root.Key)
	}

	attrs := map[string]string{}
	for _, child := range root.Children {
		if child.Kind == NodeAttr {
			attrs[child.Key] = child.Value
		}
	}
	if attrs["@name"] != `"web"` {
		t.Errorf("@name = %q, want \"web\" — most XML keeps its information in attributes", attrs["@name"])
	}
	if attrs["@replicas"] != `"3"` {
		t.Errorf("@replicas = %q, want \"3\"", attrs["@replicas"])
	}
}

// An element whose only content is text carries it, rather than gaining a child
// for it: <image>nginx</image> is one fact and should read as one row.
func TestAnElementWithOnlyTextCarriesItAsItsValue(t *testing.T) {
	doc := Open("pod.xml", KindAuto, []byte(podXML))

	image := childNamed(t, doc.Root, "image")
	if image.Value != `"nginx:latest"` {
		t.Errorf("image value = %q, want the text inline", image.Value)
	}
	for _, child := range image.Children {
		if child.Kind == NodeText {
			t.Error("image gained a #text child; the text belongs on the element")
		}
	}
}

func TestAnXMLCommentIsKept(t *testing.T) {
	doc := Open("pod.xml", KindAuto, []byte(podXML))
	for _, child := range doc.Root.Children {
		if child.Kind == NodeComment && child.Value == "the front end" {
			return
		}
	}
	t.Error("the comment is missing from the tree")
}

func TestNestedElementsKeepTheirDepth(t *testing.T) {
	doc := Open("pod.xml", KindAuto, []byte(podXML))

	ports := childNamed(t, doc.Root, "ports")
	port := childNamed(t, ports, "port")
	if port.Value != `"8080"` {
		t.Errorf("port value = %q, want \"8080\"", port.Value)
	}
	if childNamed(t, port, "@protocol").Value != `"tcp"` {
		t.Error("the nested element lost its attribute")
	}
}

func TestAMalformedXMLOpensAsText(t *testing.T) {
	doc := Open("bad.xml", KindAuto, []byte(`<a><b></a>`))
	if doc.Kind != KindPlain {
		t.Errorf("Kind = %q, want plain", doc.Kind)
	}
	if doc.ParseErr == nil {
		t.Error("ParseErr is nil; the extension declared XML")
	}
}

func childNamed(t *testing.T, parent *Node, key string) *Node {
	t.Helper()
	for _, child := range parent.Children {
		if child.Key == key {
			return child
		}
	}
	t.Fatalf("%q has no child %q", parent.Key, key)
	return nil
}

package viewer

import "testing"

func TestLevelsAreReadFromJSONLogfmtAndBareText(t *testing.T) {
	cases := []struct {
		name string
		line string
		want Level
	}{
		{"json level", `{"ts":"2026-01-01","level":"error","msg":"boom"}`, LevelError},
		{"json severity", `{"severity":"WARNING","msg":"slow"}`, LevelWarn},
		{"json lvl", `{"lvl":"debug"}`, LevelDebug},
		{"logfmt", `ts=2026-01-01 level=warn msg="disk almost full"`, LevelWarn},
		{"logfmt quoted", `level="error" msg=nope`, LevelError},
		{"bracketed", `2026-01-01 [ERROR] connection refused`, LevelError},
		{"logrus", `ERRO[0001] could not connect`, LevelError},
		{"bare info", `2026-01-01T10:00:00Z INFO  started`, LevelInfo},
		{"fatal folds into error", `[FATAL] giving up`, LevelError},
		{"panic folds into error", `PANIC: nil map`, LevelError},
		{"nothing", `just a line of output`, LevelUnknown},
	}

	for _, tc := range cases {
		t.Run(tc.name, func(t *testing.T) {
			if got := detectLevel(tc.line); got != tc.want {
				t.Errorf("detectLevel(%q) = %v, want %v", tc.line, got, tc.want)
			}
		})
	}
}

// Lowercase is refused for bare text on purpose: "error" is a word people write
// in sentences, and treating every mention of it as a level would filter out
// lines that merely talk about one.
func TestALowercaseWordInProseIsNotALevel(t *testing.T) {
	if got := detectLevel("the request failed with an error, retrying"); got != LevelUnknown {
		t.Errorf("detectLevel = %v, want unknown — a word in prose is not a level", got)
	}
}

// A level far into the line is prose, not a field.
func TestALevelWordPastTheWindowIsIgnored(t *testing.T) {
	padding := "0123456789012345678901234567890123456789012345678901234567890123456789 "
	if got := detectLevel(padding + "ERROR"); got != LevelUnknown {
		t.Errorf("detectLevel = %v, want unknown past the credible window", got)
	}
}

// The decision the whole filter rests on: a stack trace has no level on any of
// its lines, and a filter that swallowed it would destroy exactly what the user
// opened the log to read.
func TestAnUnlevelledLineInheritsTheLineAbove(t *testing.T) {
	text := `2026-01-01 [ERROR] request failed
  at handler.go:42
  at server.go:10
  at main.go:7`

	lines := ParseLog(text)
	if len(lines) != 4 {
		t.Fatalf("got %d lines, want 4", len(lines))
	}
	for i, line := range lines {
		if line.Level != LevelError {
			t.Errorf("line %d (%q) is %v, want error by inheritance", i, line.Text, line.Level)
		}
		if !line.Level.Passes(LevelWarn) {
			t.Errorf("line %d does not survive a ≥ warn filter; the trace would be lost", i)
		}
	}
}

// Inheritance has to stop somewhere, or one ERROR colours the rest of the file.
func TestABlankLineBreaksTheInheritanceChain(t *testing.T) {
	lines := ParseLog("[ERROR] boom\n  at x.go:1\n\nunrelated output")

	if lines[1].Level != LevelError {
		t.Errorf("the trace line is %v, want error", lines[1].Level)
	}
	if lines[3].Level != LevelUnknown {
		t.Errorf("the line after the blank is %v, want unknown", lines[3].Level)
	}
}

// A line nobody could classify is never hidden. Inheritance covers the lines
// that belong to an entry above them; this covers the ones that belong to
// nothing — a banner, a bare command echo, the first lines of a file.
func TestAnUnknownLineSurvivesEveryFilter(t *testing.T) {
	for _, min := range Levels {
		if !LevelUnknown.Passes(min) {
			t.Errorf("an unlevelled line is hidden at ≥ %v", min)
		}
	}
}

func TestVerbosityIsMonotone(t *testing.T) {
	cases := []struct {
		line Level
		min  Level
		want bool
	}{
		{LevelError, LevelWarn, true},
		{LevelWarn, LevelWarn, true},
		{LevelInfo, LevelWarn, false},
		{LevelDebug, LevelWarn, false},
		{LevelInfo, LevelUnknown, true}, // no filter at all
		{LevelTrace, LevelUnknown, true},
	}
	for _, tc := range cases {
		if got := tc.line.Passes(tc.min); got != tc.want {
			t.Errorf("%v.Passes(%v) = %v, want %v", tc.line, tc.min, got, tc.want)
		}
	}
}

func TestParseLogKeepsTheTextItWasGiven(t *testing.T) {
	text := "first\nsecond\nthird"
	lines := ParseLog(text)
	for i, want := range []string{"first", "second", "third"} {
		if lines[i].Text != want {
			t.Errorf("line %d = %q, want %q", i, lines[i].Text, want)
		}
	}
}

