package viewer

import (
	"os"
	"path/filepath"
	"strings"
	"testing"
)

func TestDetectionPrefersTheExtensionThenTheContent(t *testing.T) {
	cases := []struct {
		name    string
		file    string
		content string
		want    Kind
	}{
		{"json extension", "config.json", `{"a":1}`, KindJSON},
		{"xml extension", "pod.xml", `<a/>`, KindXML},
		{"log extension", "app.log", `whatever`, KindLog},

		// A named extension is taken at its word. Sniffing a .md would open a
		// Markdown file as a tree the first time someone started one with a tag.
		{"markdown starting with a tag", "README.md", `<div>hi</div>`, KindPlain},
		{"go source", "main.go", "package main", KindPlain},
		{"text holding json", "notes.txt", `{"a":1}`, KindPlain},

		// Only a file with no extension at all is guessed at.
		{"extensionless object", "dump", `  {"a":1}`, KindJSON},
		{"extensionless array", "dump", `[1,2]`, KindJSON},
		{"extensionless document", "dump", `<?xml version="1.0"?><a/>`, KindXML},
		{"Dockerfile", "Dockerfile", "FROM alpine", KindPlain},
	}

	for _, tc := range cases {
		t.Run(tc.name, func(t *testing.T) {
			if got := DetectKind(tc.file, []byte(tc.content)); got != tc.want {
				t.Errorf("DetectKind(%q) = %q, want %q", tc.file, got, tc.want)
			}
		})
	}
}

// "This looks like a log" is not a decidable question, so it is never asked.
// The kind comes from the extension or from the producer, and from nowhere else.
func TestALogKindIsNeverInferredFromContent(t *testing.T) {
	logLike := "2026-01-01 [ERROR] boom\n2026-01-01 [INFO] fine\n"

	if got := DetectKind("output", []byte(logLike)); got == KindLog {
		t.Error("an extensionless file was sniffed as a log; the kind must be declared")
	}
	if got := DetectKind("notes.txt", []byte(logLike)); got == KindLog {
		t.Error("a .txt was sniffed as a log")
	}
	if got := DetectKind("app.log", []byte(logLike)); got != KindLog {
		t.Errorf("DetectKind(app.log) = %q, want log from the extension", got)
	}
}

func TestABOMDoesNotHideTheFirstCharacter(t *testing.T) {
	withBOM := append([]byte{0xEF, 0xBB, 0xBF}, []byte(`{"a":1}`)...)
	if got := DetectKind("dump", withBOM); got != KindJSON {
		t.Errorf("DetectKind = %q, want json — the mark hid the brace", got)
	}
}

func TestABinaryFileIsRefusedRatherThanRendered(t *testing.T) {
	dir := t.TempDir()
	path := filepath.Join(dir, "image.png")
	png := []byte{0x89, 'P', 'N', 'G', 0x0D, 0x0A, 0x1A, 0x0A, 0x00, 0x00, 0x00, 0x0D}
	if err := os.WriteFile(path, png, 0o600); err != nil {
		t.Fatal(err)
	}

	if _, err := ReadFile(path); err != ErrBinary {
		t.Errorf("ReadFile = %v, want ErrBinary", err)
	}
}

func TestAFileOverTheSizeCapIsRefused(t *testing.T) {
	dir := t.TempDir()
	path := filepath.Join(dir, "huge.log")
	if err := os.WriteFile(path, []byte(strings.Repeat("a", MaxSize+1)), 0o600); err != nil {
		t.Fatal(err)
	}

	if _, err := ReadFile(path); err != ErrTooLarge {
		t.Errorf("ReadFile = %v, want ErrTooLarge", err)
	}
}

func TestAReadableTextFileComesBackWhole(t *testing.T) {
	dir := t.TempDir()
	path := filepath.Join(dir, "notes.txt")
	want := "hello\nworld\n"
	if err := os.WriteFile(path, []byte(want), 0o600); err != nil {
		t.Fatal(err)
	}

	data, err := ReadFile(path)
	if err != nil {
		t.Fatalf("ReadFile: %v", err)
	}
	if string(data) != want {
		t.Errorf("ReadFile = %q, want %q", data, want)
	}
}

func TestADirectoryIsNotADocument(t *testing.T) {
	if _, err := ReadFile(t.TempDir()); err == nil {
		t.Error("ReadFile accepted a directory")
	}
}

func TestAFileSourceNamesItselfByItsBase(t *testing.T) {
	src := NewFileSource(filepath.Join("a", "b", "config.json"))
	if got := src.Name(); got != "config.json" {
		t.Errorf("Name = %q, want config.json", got)
	}
	if got := src.Kind(); got != KindAuto {
		t.Errorf("Kind = %q, want auto — a file browser does not know what it is opening", got)
	}
}

package viewer

import (
	"strings"
	"testing"
)

// The invariant every caller depends on. The rendered lines are matched against
// the document's real ones, so a lexer that dropped or added a byte would
// desynchronise the two — and the failure would show up as a viewport scrolled
// to the wrong place, a long way from its cause.
func TestHighlightingReproducesTheInputExactly(t *testing.T) {
	cases := []struct {
		kind Kind
		text string
	}{
		{KindJSON, "{\n  \"name\": \"nginx\",\n  \"n\": 42,\n  \"ok\": true,\n  \"z\": null\n}"},
		{KindXML, "<?xml version=\"1.0\"?>\n<!-- c -->\n<root a=\"1\">text</root>\n"},
		{KindPlain, "just\nsome\ttext\n"},
		{KindLog, "2026-01-01 [ERROR] boom\n"},
		{KindJSON, ""},
		{KindJSON, "{not really json"},
	}

	for _, tc := range cases {
		var rebuilt strings.Builder
		for _, token := range Tokenize(tc.kind, tc.text) {
			rebuilt.WriteString(token.Text)
		}
		if rebuilt.String() != tc.text {
			t.Errorf("%s: tokens rebuild %q, want %q", tc.kind, rebuilt.String(), tc.text)
		}
	}
}

func TestJSONTokensAreClassified(t *testing.T) {
	tokens := Tokenize(KindJSON, `{"name": "nginx", "n": 42, "ok": true}`)

	seen := map[TokenClass]string{}
	for _, token := range tokens {
		if _, ok := seen[token.Class]; !ok {
			seen[token.Class] = token.Text
		}
	}

	for class, want := range map[TokenClass]string{
		ClassKey:     `"name"`,
		ClassString:  `"nginx"`,
		ClassNumber:  `42`,
		ClassLiteral: `true`,
		ClassPunct:   `{`,
	} {
		if seen[class] != want {
			t.Errorf("class %d first matched %q, want %q", class, seen[class], want)
		}
	}
}

func TestXMLTagsAndAttributesAreClassifiedApart(t *testing.T) {
	tokens := Tokenize(KindXML, `<!-- c --><root a="1">text</root>`)

	classes := map[TokenClass]bool{}
	for _, token := range tokens {
		classes[token.Class] = true
	}
	for _, want := range []TokenClass{ClassComment, ClassTag, ClassAttr, ClassString} {
		if !classes[want] {
			t.Errorf("class %d never appeared in an XML document that has one", want)
		}
	}
	if classes[ClassKey] {
		t.Error("an XML tag was classified as a JSON key")
	}
}

// A log's colour comes from its level, one whole line at a time, which is a
// different question from what a token is. Asking chroma would answer the wrong
// one.
func TestALogIsNotTokenized(t *testing.T) {
	tokens := Tokenize(KindLog, "2026-01-01 [ERROR] boom\nsecond line\n")
	if len(tokens) != 1 || tokens[0].Class != ClassText {
		t.Errorf("Tokenize returned %d tokens, want one plain run", len(tokens))
	}
}

package viewer

import (
	"strings"
	"testing"
)

const nestedJSON = `{"a":{"b":1,"c":2},"d":3}`

func TestFlattenWalksInDocumentOrder(t *testing.T) {
	doc := Open("n.json", KindAuto, []byte(nestedJSON))

	var keys []string
	for _, flat := range Flatten(doc.Root, nil) {
		keys = append(keys, flat.Node.Key)
	}
	// The root carries no key; then a, its two children, then d.
	if got := strings.Join(keys, ","); got != ",a,b,c,d" {
		t.Errorf("flattened keys = %q, want \",a,b,c,d\"", got)
	}
}

func TestFlattenReportsTheDepthARowRendersAt(t *testing.T) {
	doc := Open("n.json", KindAuto, []byte(nestedJSON))

	depths := map[string]int{}
	for _, flat := range Flatten(doc.Root, nil) {
		depths[flat.Node.Key] = flat.Depth
	}
	for key, want := range map[string]int{"a": 1, "b": 2, "c": 2, "d": 1} {
		if depths[key] != want {
			t.Errorf("depth of %q = %d, want %d", key, depths[key], want)
		}
	}
}

func TestCollapsingANodeHidesItsDescendants(t *testing.T) {
	doc := Open("n.json", KindAuto, []byte(nestedJSON))

	a := doc.Root.Children[0]
	collapsed := map[int]bool{a.ID: true}

	var keys []string
	for _, flat := range Flatten(doc.Root, collapsed) {
		keys = append(keys, flat.Node.Key)
	}
	if got := strings.Join(keys, ","); got != ",a,d" {
		t.Errorf("flattened keys = %q, want \",a,d\" — b and c are inside a", got)
	}
}

func TestCollapsingTheRootLeavesOneRow(t *testing.T) {
	doc := Open("n.json", KindAuto, []byte(nestedJSON))

	rows := Flatten(doc.Root, map[int]bool{doc.Root.ID: true})
	if len(rows) != 1 {
		t.Errorf("got %d rows with the root collapsed, want 1", len(rows))
	}
}

// Identity is an int assigned in document order, and every node gets a distinct
// one. The view's expansion set is keyed on it, so a collision would collapse
// two unrelated branches together.
func TestEveryNodeHasADistinctID(t *testing.T) {
	doc := Open("n.json", KindAuto, []byte(`{"a":{"b":[1,2,{"c":3}]},"d":null}`))

	seen := map[int]bool{}
	for _, flat := range Flatten(doc.Root, nil) {
		if seen[flat.Node.ID] {
			t.Fatalf("node ID %d appears twice", flat.Node.ID)
		}
		seen[flat.Node.ID] = true
	}
	if len(seen) != doc.NodeCount() {
		t.Errorf("flatten yielded %d nodes, NodeCount says %d", len(seen), doc.NodeCount())
	}
}

// An empty container has nothing to expand into, and a chevron promising a
// level that is not there is worse than no chevron.
func TestAnEmptyContainerOffersNoChevron(t *testing.T) {
	doc := Open("e.json", KindAuto, []byte(`{"empty":{},"list":[],"full":{"a":1}}`))

	for _, tc := range []struct {
		key  string
		want bool
	}{{"empty", false}, {"list", false}, {"full", true}} {
		node := childNamed(t, doc.Root, tc.key)
		if got := node.HasChildren(); got != tc.want {
			t.Errorf("%q HasChildren = %v, want %v", tc.key, got, tc.want)
		}
	}
}

func TestFlattenOfNothingIsNothing(t *testing.T) {
	if rows := Flatten(nil, nil); rows != nil {
		t.Errorf("Flatten(nil) = %v, want nil", rows)
	}
}

// A value carrying a newline would end its row halfway and push the rest onto a
// line of its own.
func TestAStringValueIsEscapedToOneLine(t *testing.T) {
	doc := Open("s.json", KindAuto, []byte(`{"k":"first\nsecond\ttabbed"}`))

	value := childNamed(t, doc.Root, "k").Value
	if strings.ContainsAny(value, "\n\t") {
		t.Errorf("value %q still holds a raw control character", value)
	}
	if value != `"first\nsecond\ttabbed"` {
		t.Errorf("value = %q, want the escapes made visible", value)
	}
}

