package viewer

import (
	"github.com/anthnel/devdesk/internal/command"
	"github.com/anthnel/devdesk/internal/viewer"
)

// OpenRequestMsg asks the router to open a document. It is what every producer
// emits — workspaces for a file, containers for an inspect or a log — and the
// only thing they have to agree on.
//
// It carries the source rather than the content: the read happens in the
// viewer's own Init, so one place decides what is too large or not text, and one
// place reports it. A producer that loaded the bytes itself would each have to
// answer that question again, and answer it the same way.
type OpenRequestMsg struct {
	Source viewer.Source
}

// DocumentLoadedMsg carries the result of a Load back into Update (Rule 110).
type DocumentLoadedMsg struct {
	Name    string
	Kind    viewer.Kind
	Content []byte
	Err     error
}

// BackToOriginMsg asks the router to return to the view the document was opened
// from. It mirrors security.BackToOriginMsg, and for the same reason: the view
// knows where it came from, the router knows how to get there.
type BackToOriginMsg struct {
	Origin command.ViewType
}

// PagerExitMsg comes back when the system pager or the follow process ends.
type PagerExitMsg struct {
	Err error
}

// clearFooterMsg drops a transient footer message after its three seconds
// (Rule 128).
type clearFooterMsg struct{}

package viewer

import (
	"github.com/charmbracelet/lipgloss"

	"github.com/anthnel/devdesk/internal/ui/theme"
	"github.com/anthnel/devdesk/internal/viewer"
)

// syntaxStyle is the colour a token class renders in.
//
// The background is set on every style, without exception. lipgloss does not
// inherit one (Rule 115), and a styled run closes with a reset that takes the
// app background with it — so a single uncoloured token would show the
// terminal's own background from there to the end of the line. Setting it
// everywhere is what makes that unexpressible rather than a thing to remember.
//
// This mapping lives here, in the UI package, rather than in theme or in
// internal/viewer: it is the one place that already imports both, so neither of
// them has to learn about the other.
func syntaxStyle(class viewer.TokenClass) lipgloss.Style {
	base := lipgloss.NewStyle().Background(theme.ColorBackground)

	switch class {
	case viewer.ClassKey:
		return base.Foreground(theme.ColorSyntaxKey)
	case viewer.ClassString:
		return base.Foreground(theme.ColorSyntaxString)
	case viewer.ClassNumber:
		return base.Foreground(theme.ColorSyntaxNumber)
	case viewer.ClassLiteral:
		return base.Foreground(theme.ColorSyntaxLiteral)
	case viewer.ClassPunct:
		return base.Foreground(theme.ColorSyntaxPunct)
	case viewer.ClassTag:
		return base.Foreground(theme.ColorSyntaxTag)
	case viewer.ClassAttr:
		return base.Foreground(theme.ColorSyntaxAttr)
	case viewer.ClassComment:
		return base.Foreground(theme.ColorSyntaxComment)
	default:
		return base.Foreground(theme.ColorText)
	}
}

// levelStyle colours a whole log line by its severity.
//
// A log line is styled in one piece rather than per token: its level is a fact
// about the entry, and picking out an ERROR at a glance is the entire reason
// anyone filters a log. Info is left in the default text colour — it is the
// majority state, and colouring the majority informs no one (Rule 122's colour
// discipline).
func levelStyle(level viewer.Level) lipgloss.Style {
	switch level {
	case viewer.LevelError:
		return theme.StatusErrorStyle.Background(theme.ColorBackground)
	case viewer.LevelWarn:
		return theme.StatusWarningStyle.Background(theme.ColorBackground)
	case viewer.LevelDebug, viewer.LevelTrace:
		return theme.DimStyle.Background(theme.ColorBackground)
	default:
		return lipgloss.NewStyle().Background(theme.ColorBackground).Foreground(theme.ColorText)
	}
}

// nodeStyle colours a tree value by what the node holds.
//
// A tree cell carries exactly one class, which is why the tree can be a
// datatable at all: datatable applies one Style per cell and cannot express
// several colours inside one, and it never has to here.
func nodeStyle(kind viewer.NodeKind) lipgloss.Style {
	return syntaxStyle(nodeClass(kind))
}

func nodeClass(kind viewer.NodeKind) viewer.TokenClass {
	switch kind {
	case viewer.NodeString, viewer.NodeText:
		return viewer.ClassString
	case viewer.NodeNumber:
		return viewer.ClassNumber
	case viewer.NodeBool, viewer.NodeNull:
		return viewer.ClassLiteral
	case viewer.NodeObject, viewer.NodeArray:
		return viewer.ClassPunct
	case viewer.NodeComment:
		return viewer.ClassComment
	default:
		return viewer.ClassText
	}
}

// keyClass is how a node's own name is coloured: an XML attribute reads as an
// attribute, an element as a tag, a JSON key as a key.
func keyClass(kind viewer.NodeKind) viewer.TokenClass {
	switch kind {
	case viewer.NodeAttr:
		return viewer.ClassAttr
	case viewer.NodeElement:
		return viewer.ClassTag
	case viewer.NodeComment:
		return viewer.ClassComment
	default:
		return viewer.ClassKey
	}
}

package viewer

import (
	"strings"

	"github.com/anthnel/devdesk/internal/viewer"
)

// docLine is one source line, kept as the token spans it is made of.
//
// The spans are the point. Wrapping counts runes, and an ANSI escape's bytes
// count as width — the same hazard Rule 122 describes for table cells — so a
// line that has already been coloured cannot be wrapped without the cut landing
// inside an escape sequence. Keeping the line as tokens means it is wrapped
// while it is still plain and coloured afterwards, which is the only order that
// works.
type docLine struct {
	Tokens []viewer.Token
	Plain  string
	Level  viewer.Level
}

// buildLines splits a document into styled-per-line spans.
//
// It is called when the document loads and when `c` toggles, and not otherwise:
// tokenising five megabytes per frame is not viable, and the filter and the
// wrap both work on the result rather than redoing it.
func buildLines(doc viewer.Document, highlight bool) []docLine {
	tokens := []viewer.Token{{Class: viewer.ClassText, Text: doc.Text}}
	if highlight {
		tokens = viewer.Tokenize(doc.Kind, doc.Text)
	}

	lines := splitTokenLines(tokens)

	// A log's level rides on the line, not on a token. The two lists are the
	// same split of the same text — ParseLog and splitTokenLines both cut on
	// "\n" — so they line up index for index.
	for i := range lines {
		if i < len(doc.Lines) {
			lines[i].Level = doc.Lines[i].Level
		}
	}
	return lines
}

// splitTokenLines cuts a document-wide token stream into one slice of tokens per
// line, splitting any token that spans a newline.
func splitTokenLines(tokens []viewer.Token) []docLine {
	var lines []docLine
	var current []viewer.Token
	var plain strings.Builder

	flush := func() {
		lines = append(lines, docLine{Tokens: current, Plain: plain.String()})
		current = nil
		plain.Reset()
	}

	for _, token := range tokens {
		parts := strings.Split(token.Text, "\n")
		for i, part := range parts {
			if i > 0 {
				flush()
			}
			if part == "" {
				continue
			}
			current = append(current, viewer.Token{Class: token.Class, Text: part})
			plain.WriteString(part)
		}
	}
	flush()

	// A document ending in a newline produces a trailing empty line, which is
	// true of the text but renders as a blank row nobody asked for.
	if n := len(lines); n > 1 && lines[n-1].Plain == "" {
		lines = lines[:n-1]
	}
	return lines
}

// wrapTokens splits a line into segments no wider than width runes, cutting
// tokens where a segment ends.
//
// It breaks at the width rather than at a word boundary, for the same reason
// viewer.WrapLines does: the content here is a log line, a stack trace or a
// minified document, where the columns carry meaning.
func wrapTokens(tokens []viewer.Token, width int) [][]viewer.Token {
	if width <= 0 {
		return [][]viewer.Token{tokens}
	}

	var segments [][]viewer.Token
	var current []viewer.Token
	room := width

	for _, token := range tokens {
		runes := []rune(token.Text)
		for len(runes) > 0 {
			if room == 0 {
				segments = append(segments, current)
				current, room = nil, width
			}
			take := min(room, len(runes))
			current = append(current, viewer.Token{Class: token.Class, Text: string(runes[:take])})
			runes = runes[take:]
			room -= take
		}
	}
	return append(segments, current)
}

// render paints a segment. A log line takes one style for the whole of it, so
// that an ERROR is picked out at a glance; anything else is coloured token by
// token.
func renderSegment(tokens []viewer.Token, level viewer.Level, isLog bool) string {
	if isLog {
		var plain strings.Builder
		for _, token := range tokens {
			plain.WriteString(token.Text)
		}
		return levelStyle(level).Render(plain.String())
	}

	var out strings.Builder
	for _, token := range tokens {
		out.WriteString(syntaxStyle(token.Class).Render(token.Text))
	}
	return out.String()
}

package viewer

import (
	"strings"

	"github.com/charmbracelet/lipgloss"

	"github.com/anthnel/devdesk/internal/ui/datatable"
	"github.com/anthnel/devdesk/internal/ui/theme"
	"github.com/anthnel/devdesk/internal/viewer"
)

// treeRow is a node with what the screen knows about it.
//
// It exists for the reason imageRow and explorerRow do: datatable's columns are
// built once, in New, and close over nothing, so anything a cell needs beyond
// the domain object — the depth it renders at, whether it is expanded — has to
// travel on the row.
type treeRow struct {
	Node     *viewer.Node
	Depth    int
	Expanded bool
	// Highlight is off when `c` is off, and the row then renders in the plain
	// text colour. It rides on the row for the same reason as the rest.
	Highlight bool
}

// indentUnit is one level of nesting. Two spaces: a JSON document nests deeply
// and four would push the value column off a narrow terminal by the third level.
const indentUnit = "  "

// treeColumns are the two the tree shows. Neither declares Less or Search, and
// both omissions are deliberate:
//
//   - Sorting would destroy the order the file gave it, which is why the parsers
//     read a token stream in the first place. A JSON object read back
//     alphabetised is a different document.
//   - A text filter would match a child and hide its parents, leaving rows at a
//     depth with nothing above them to explain it.
//
// datatable advertises `/` and `.` from these fields, so leaving them nil is
// also what keeps the two keys off the shortcut list (Rule 138).
func treeColumns() []datatable.Column[treeRow] {
	return []datatable.Column[treeRow]{
		{
			Title: "Key", MinWidth: 20, Flex: 2,
			Cell:  treeKeyCell,
			Style: treeKeyStyle,
		},
		{
			Title: "Value", MinWidth: 20, Flex: 3,
			Cell:  func(r treeRow) string { return r.Node.Value },
			Style: treeValueStyle,
		},
	}
}

// treeKeyCell is the indentation, the chevron and the name — plain text, because
// it is measured and truncated before anything is applied to it (Rule 122).
func treeKeyCell(r treeRow) string {
	return strings.Repeat(indentUnit, r.Depth) + chevronFor(r) + " " + r.Node.Key
}

// chevronFor is the glyph without its colour: a leaf gets a space rather than a
// chevron, because a chevron promising a level that is not there is worse than
// none.
func chevronFor(r treeRow) string {
	switch {
	case !r.Node.HasChildren():
		return " "
	case r.Expanded:
		return theme.IconChevronDown
	default:
		return theme.IconChevronRight
	}
}

func treeKeyStyle(r treeRow) lipgloss.Style {
	if !r.Highlight {
		return lipgloss.NewStyle()
	}
	return syntaxStyle(keyClass(r.Node.Kind))
}

func treeValueStyle(r treeRow) lipgloss.Style {
	if !r.Highlight {
		return lipgloss.NewStyle()
	}
	return nodeStyle(r.Node.Kind)
}

// treeRows flattens the document for a given expansion state.
func (m *Model) treeRows() []treeRow {
	flat := viewer.Flatten(m.doc.Root, m.collapsed)
	rows := make([]treeRow, 0, len(flat))
	for _, node := range flat {
		rows = append(rows, treeRow{
			Node:      node.Node,
			Depth:     node.Depth,
			Expanded:  !m.collapsed[node.Node.ID],
			Highlight: m.highlight,
		})
	}
	return rows
}

// rebuildTree puts the current expansion state on screen, keeping the cursor
// where it was. datatable clamps it, so a collapse that removes the rows below
// the cursor leaves it on the last row that still exists rather than nowhere.
func (m *Model) rebuildTree() {
	m.tree.SetItems(m.treeRows())
}

// toggleNode expands or collapses the selected node.
//
// Returning whether anything happened is what lets the caller leave `←` and `→`
// free to mean nothing on a leaf, rather than swallowing the key.
func (m *Model) toggleNode(expand bool) bool {
	row, ok := m.tree.Selected()
	if !ok || !row.Node.HasChildren() {
		return false
	}
	if m.collapsed[row.Node.ID] == !expand {
		return false // already in the asked-for state
	}
	if expand {
		delete(m.collapsed, row.Node.ID)
	} else {
		m.collapsed[row.Node.ID] = true
	}
	m.rebuildTree()
	return true
}

package viewer

import (
	"strings"

	"github.com/anthnel/devdesk/internal/ui/theme"
	"github.com/anthnel/devdesk/internal/viewer"
)

// rebuildText renders the text pane and hands it to the viewport.
//
// It is called when the document loads, when `c`, `w` or `v` changes, when the
// search query changes and when the width changes — and at no other time.
// View() must stay read-only (Rule 110), and re-rendering five megabytes per
// frame would not be viable even if it did not.
func (m *Model) rebuildText() {
	width := m.textViewport.Width
	query := strings.ToLower(strings.TrimSpace(m.bar.SearchQuery()))
	isLog := m.doc.Kind == viewer.KindLog

	var out []string
	m.matchedLines = 0

	for _, line := range m.lines {
		if isLog && !line.Level.Passes(m.minLevel) {
			continue
		}
		if query != "" && !strings.Contains(strings.ToLower(line.Plain), query) {
			continue
		}
		m.matchedLines++

		segments := [][]viewer.Token{line.Tokens}
		if m.wrap && width > 0 {
			segments = wrapTokens(line.Tokens, width)
		}
		for _, segment := range segments {
			// Padded to the full width: lipgloss inherits no background
			// (Rule 115), so a line shorter than the pane would show the
			// terminal's own from its last character to the right margin.
			out = append(out, theme.PadWithBg(renderSegment(segment, line.Level, isLog), width))
		}
	}

	if len(out) == 0 {
		out = append(out, theme.PadWithBg(theme.DimStyle.Render(m.emptyTextMessage()), width))
	}

	m.textViewport.SetContent(strings.Join(out, "\n"))
}

// emptyTextMessage says why the pane is empty, which is never obvious: an empty
// document, a filter that matched nothing and a search that matched nothing all
// look identical, and only one of them is the user's own doing.
func (m *Model) emptyTextMessage() string {
	switch {
	case m.bar.SearchQuery() != "":
		return "No line matches " + m.bar.SearchQuery()
	case m.minLevel != viewer.LevelUnknown:
		return "No line at " + minLevelLabel(m.minLevel) + " or above"
	default:
		return "Empty document"
	}
}

// minLevelLabel is how a verbosity filter reads, in the footer token and in the
// header alike — one spelling, so the two cannot drift.
func minLevelLabel(level viewer.Level) string {
	if level == viewer.LevelUnknown {
		return "all"
	}
	return "≥ " + level.String()
}

// cycleVerbosity advances the minimum level: all, then each level in turn, then
// back to all.
//
// One key rather than four toggles, because a minimum is what "verbosity" means
// and log levels are monotone — nobody wants warn but not error. The bar shows
// it as a single token, and disappears entirely at `all` (Rule 136: no filter,
// no bar).
func (m *Model) cycleVerbosity() {
	next := viewer.LevelUnknown
	switch m.minLevel {
	case viewer.LevelUnknown:
		next = viewer.Levels[0]
	default:
		for i, level := range viewer.Levels {
			if level == m.minLevel && i+1 < len(viewer.Levels) {
				next = viewer.Levels[i+1]
			}
		}
	}
	m.minLevel = next
	m.syncVerbosityToken()
	m.rebuildText()
}

// syncVerbosityToken keeps the filter bar's token showing the level in force.
//
// The label carries the value, so SetTokens is given the active flag explicitly:
// it preserves an active state by matching labels, and "≥ warn" is not the label
// "≥ info" was.
func (m *Model) syncVerbosityToken() {
	if m.doc.Kind != viewer.KindLog || m.minLevel == viewer.LevelUnknown {
		m.bar.SetTokens(nil)
		return
	}
	m.bar.SetTokens([]components.FilterToken{{Label: minLevelLabel(m.minLevel), Active: true}})
}

