package viewer

import (
	"github.com/charmbracelet/bubbles/viewport"

	"github.com/anthnel/devdesk/internal/command"
	"github.com/anthnel/devdesk/internal/config"
	"github.com/anthnel/devdesk/internal/ui/components"
	"github.com/anthnel/devdesk/internal/ui/datatable"
	"github.com/anthnel/devdesk/internal/viewer"
)

// display is how the document is shown. Two values, not three: "plain text" is
// this pane with the colour off, and giving it a display of its own would make
// one screen reachable two ways — the shape §3.9 removed from the secret
// backend and the deleted `:theme` command.
type display int

const (
	displayTree display = iota
	displayText
)

// Model is the document viewer.
type Model struct {
	config *config.Config
	width  int
	height int

	// source is where the document came from, and it is kept rather than
	// discarded after the first read: reload, follow and the timestamps toggle
	// are all questions for the origin, not for the bytes.
	source  viewer.Source
	doc     viewer.Document
	loading bool

	display   display
	highlight bool
	wrap      bool
	minLevel  viewer.Level

	// The tree half.
	tree      datatable.Model[treeRow]
	collapsed map[int]bool

	// The text half. lines is the document cut into token spans; it is rebuilt
	// when the document loads and when `c` toggles, never per frame.
	lines        []docLine
	textViewport viewport.Model
	bar          components.FilterBar
	matchedLines int

	// OriginView is where esc returns to. The router sets it from whatever view
	// asked for the document.
	OriginView command.ViewType

	footerError string
	footerInfo  string
}

// New builds an empty viewer.
//
// It exists so the router can create the view like any other — the contract test
// builds every view and asks it for a title and its shortcuts. On screen it says
// there is nothing open, which is the truth and is only ever reached by opening
// the view without a document.
func New(cfg *config.Config) Model {
	return Model{
		config:       cfg,
		highlight:    true,
		collapsed:    make(map[int]bool),
		tree:         datatable.New(datatable.Config[treeRow]{Columns: treeColumns(), SortColumn: -1}),
		textViewport: viewport.New(0, 0),
		bar:          components.NewFilterBar(),
		display:      displayText,
	}
}

// NewWithSource builds a viewer that will load this source when it starts.
func NewWithSource(cfg *config.Config, source viewer.Source) Model {
	m := New(cfg)
	m.source = source
	m.loading = true
	return m
}

// Name is what the header calls the document.
func (m Model) Name() string {
	if m.doc.Name != "" {
		return m.doc.Name
	}
	if m.source != nil {
		return m.source.Name()
	}
	return ""
}

// hasDocument reports whether anything has been loaded. Most of the keys and
// every shortcut but esc are conditional on it (Rule 130).
func (m Model) hasDocument() bool {
	return m.doc.Name != "" || m.doc.Text != ""
}

// structured reports whether the tree display is available at all.
func (m Model) structured() bool {
	return m.doc.Kind.Structured() && m.doc.Root != nil
}

// isLog reports whether the verbosity filter applies.
func (m Model) isLog() bool { return m.doc.Kind == viewer.KindLog }

// applyDocument installs a freshly parsed document and settles every piece of
// state that depends on it.
//
// One function rather than a handful of assignments at the call sites: a
// document arrives from a first load, from a reload and from a timestamps
// toggle, and a display left pointing at a tree that the new document does not
// have would render an empty pane with nothing to say why.
func (m *Model) applyDocument(doc viewer.Document) {
	m.doc = doc
	m.loading = false
	m.collapsed = make(map[int]bool)
	m.lines = buildLines(doc, m.highlight)

	// A structured document opens on its tree, which is what the request asked
	// for: a .json opens as json, a .xml as xml. Everything else has no tree to
	// open on.
	if m.structured() {
		m.display = displayTree
	} else {
		m.display = displayText
	}

	// A verbosity filter left over from a previous document would hide lines of
	// this one for a reason the user set on something else.
	if !m.isLog() {
		m.minLevel = viewer.LevelUnknown
	}
	m.syncVerbosityToken()

	m.rebuildTree()
	m.tree.GotoTop()
	m.rebuildText()
	m.textViewport.GotoTop()

	if doc.ParseErr != nil {
		m.footerInfo = "Malformed " + doc.Name + " — showing text"
	}
}

// toggleHighlight is `c`. It rebuilds the spans, which is the one thing that
// costs anything here — and the reason it is a key rather than something
// recomputed on every frame.
func (m *Model) toggleHighlight() {
	m.highlight = !m.highlight
	m.lines = buildLines(m.doc, m.highlight)
	m.rebuildTree()
	m.rebuildText()
}

// toggleDisplay is `f`. It does nothing for a document with no tree, and the
// shortcut is hidden in that case rather than offered and ignored.
func (m *Model) toggleDisplay() {
	if !m.structured() {
		return
	}
	if m.display == displayTree {
		m.display = displayText
		return
	}
	m.display = displayTree
}

// formatLabel is what the header prints: the kind and the display, and the
// filter when there is one.
func (m Model) formatLabel() string {
	if !m.hasDocument() {
		return "-"
	}
	label := m.doc.Kind.String()
	if m.structured() {
		if m.display == displayTree {
			return label + " · tree"
		}
		return label + " · text"
	}
	if m.isLog() && m.minLevel != viewer.LevelUnknown {
		return label + " · " + minLevelLabel(m.minLevel)
	}
	return label
}

package viewer

import (
	"log"
	"time"

	tea "github.com/charmbracelet/bubbletea"

	"github.com/anthnel/devdesk/internal/viewer"
)

// Init loads the source, if there is one.
func (m Model) Init() tea.Cmd {
	if m.source == nil {
		return nil
	}
	return loadCmd(m.source)
}

// loadCmd fetches a source's content. Every read the viewer does goes through
// here, on a command's goroutine — Update does no I/O (Rule 110).
func loadCmd(source viewer.Source) tea.Cmd {
	return func() tea.Msg {
		data, err := source.Load()
		return DocumentLoadedMsg{
			Name:    source.Name(),
			Kind:    source.Kind(),
			Content: data,
			Err:     err,
		}
	}
}

// clearFooterCmd drops a footer message after the three seconds every one of
// them gets (Rule 128).
func clearFooterCmd() tea.Cmd {
	return tea.Tick(3*time.Second, func(time.Time) tea.Msg { return clearFooterMsg{} })
}

// InEditMode keeps command mode out while the search field has the keyboard.
func (m Model) InEditMode() bool { return m.bar.InEditMode() }

// FilterBarVisible tells the router to close the viewport border into the bar
// (Rule 136).
func (m Model) FilterBarVisible() bool {
	return m.bar.IsVisible() && m.display == displayText
}

func (m Model) Update(msg tea.Msg) (tea.Model, tea.Cmd) {
	switch msg := msg.(type) {
	case tea.WindowSizeMsg:
		m.resize(msg.Width, msg.Height)
		return m, nil

	case tea.KeyMsg:
		return m.handleKeyMsg(msg)

	case DocumentLoadedMsg:
		return m.handleDocumentLoaded(msg)

	case PagerExitMsg:
		return m.handlePagerExit(msg)

	case clearFooterMsg:
		m.footerError = ""
		m.footerInfo = ""
		return m, nil
	}
	return m, nil
}

// resize lays out whichever half is on screen. Both are sized, not just the
// active one: a `f` between two window sizes would otherwise show a pane laid
// out for the previous width.
func (m *Model) resize(width, height int) {
	m.width = width
	m.height = height

	m.tree.Resize(width, height)

	m.textViewport.Width = width
	m.textViewport.Height = max(height, 1)
	m.bar.Resize(width)
	m.rebuildText() // the wrap and the padding both depend on the width
}

func (m Model) handleDocumentLoaded(msg DocumentLoadedMsg) (tea.Model, tea.Cmd) {
	m.loading = false
	if msg.Err != nil {
		log.Printf("ERROR [viewer] load %s: %v", msg.Name, msg.Err)
		m.footerError = loadErrorMessage(msg.Err)
		return m, clearFooterCmd()
	}
	m.footerError = ""
	m.applyDocument(viewer.Open(msg.Name, msg.Kind, msg.Content))
	if m.footerInfo != "" {
		return m, clearFooterCmd()
	}
	return m, nil
}

// loadErrorMessage names the two refusals and hides the rest behind the log
// (Rule 128): "file is too large" is something the user can act on, an OS error
// string in a footer is not.
func loadErrorMessage(err error) string {
	switch err {
	case viewer.ErrTooLarge:
		return "File is too large to view"
	case viewer.ErrBinary:
		return "Not a text file"
	default:
		return "Failed to open — check logs"
	}
}

func (m Model) handlePagerExit(msg PagerExitMsg) (tea.Model, tea.Cmd) {
	if msg.Err != nil {
		log.Printf("ERROR [viewer] pager: %v", msg.Err)
	}
	// Whatever the pager or the follow showed, the document may have moved on
	// while the TUI was suspended. Reloading is the only way back to something
	// true.
	if m.source == nil {
		return m, nil
	}
	m.loading = true
	return m, loadCmd(m.source)
}

func (m Model) handleKeyMsg(msg tea.KeyMsg) (tea.Model, tea.Cmd) {
	if m.bar.InEditMode() {
		var cmd tea.Cmd
		m.bar, cmd = m.bar.Update(msg)
		m.rebuildText()
		return m, cmd
	}

	switch msg.String() {
	case "esc":
		return m.goBack()
	case "f":
		m.toggleDisplay()
		return m, nil
	case "c":
		m.toggleHighlight()
		return m, nil
	case "ctrl+r":
		return m.reload()
	}

	if m.display == displayTree {
		return m.handleTreeKey(msg)
	}
	return m.handleTextKey(msg)
}

// goBack returns to whoever opened the document. With no origin — the empty
// viewer the router builds for its own contract test — there is nowhere to go,
// and swallowing esc silently is better than switching to a view nobody asked
// for.
func (m Model) goBack() (tea.Model, tea.Cmd) {
	if m.OriginView == "" {
		return m, nil
	}
	origin := m.OriginView
	return m, func() tea.Msg { return BackToOriginMsg{Origin: origin} }
}

func (m Model) reload() (tea.Model, tea.Cmd) {
	if m.source == nil {
		return m, nil
	}
	m.loading = true
	return m, loadCmd(m.source)
}

func (m Model) handleTreeKey(msg tea.KeyMsg) (tea.Model, tea.Cmd) {
	switch msg.String() {
	case "right", "l":
		m.toggleNode(true)
		return m, nil
	case "left", "h":
		m.toggleNode(false)
		return m, nil
	}
	return m, m.tree.Update(msg)
}

func (m Model) handleTextKey(msg tea.KeyMsg) (tea.Model, tea.Cmd) {
	switch msg.String() {
	case "/":
		return m, m.bar.ActivateSearch()
	case "w":
		m.wrap = !m.wrap
		m.rebuildText()
		return m, nil
	case "v":
		if !m.isLog() {
			return m, nil
		}
		m.cycleVerbosity()
		return m, nil
	case "t":
		return m.toggleTimestamps()
	case "ctrl+f":
		return m.follow()
	case "e":
		return m.openPager()

	// The scroll keys. `q` is deliberately absent: it is the application's quit
	// key (Rule 111), and the logs pane this replaced was the one screen that
	// swallowed it.
	case "up", "k":
		m.textViewport.ScrollUp(1)
	case "down", "j":
		m.textViewport.ScrollDown(1)
	case "pgup":
		m.textViewport.HalfPageUp()
	case "pgdown":
		m.textViewport.HalfPageDown()
	case "g", "home":
		m.textViewport.GotoTop()
	case "G", "end":
		m.textViewport.GotoBottom()
	}
	return m, nil
}

// ── The source's optional capabilities ───────────────────────────────────────
//
// Each is probed with a type assertion, the way the router probes FooterView.
// They are three single-method interfaces rather than one with three methods
// precisely so there is no half-satisfied state: CLAUDE.md's HeaderView warning
// is about a view supplying two of four methods and silently satisfying none.

// timestamps returns the source's timestamp capability, if it has one.
func (m Model) timestamps() (viewer.Timestamped, bool) {
	src, ok := m.source.(viewer.Timestamped)
	return src, ok
}

func (m Model) followable() (viewer.Followable, bool) {
	src, ok := m.source.(viewer.Followable)
	return src, ok
}

func (m Model) pageable() (viewer.Pageable, bool) {
	src, ok := m.source.(viewer.Pageable)
	return src, ok
}

// timestampsOn tracks the toggle rather than asking the source, which holds it
// but cannot be interrogated through the interface — WithTimestamps returns a
// new source rather than mutating one, so nothing is shared with a command
// already in flight (Rule 110).
func (m Model) toggleTimestamps() (tea.Model, tea.Cmd) {
	src, ok := m.timestamps()
	if !ok {
		return m, nil
	}
	m.showTimestamps = !m.showTimestamps
	m.source = src.WithTimestamps(m.showTimestamps)
	m.loading = true
	return m, loadCmd(m.source)
}

func (m Model) follow() (tea.Model, tea.Cmd) {
	src, ok := m.followable()
	if !ok {
		return m, nil
	}
	return m, tea.ExecProcess(src.FollowCmd(), func(err error) tea.Msg {
		return PagerExitMsg{Err: err}
	})
}

// openPager hands the document to the system pager.
//
// It survives for one source and deliberately: `less` handles a gigabyte and
// follows it, which a viewport holding the whole document in memory never will.
// Every other pager path in the application is gone.
func (m Model) openPager() (tea.Model, tea.Cmd) {
	src, ok := m.pageable()
	if !ok {
		return m, nil
	}
	return m, tea.ExecProcess(src.PagerCmd(), func(err error) tea.Msg {
		return PagerExitMsg{Err: err}
	})
}

