		script := fmt.Sprintf(`docker logs --tail 500 %s > "%%TEMP%%\devdesk-logs.txt" 2>&1 && more "%%TEMP%%\devdesk-logs.txt"`, m.logsContainerID)
		pagerCmd = exec.Command("cmd", "/c", script)
