// Returning from the pager or the follow stream reloads: the document may have
// moved on while the TUI was suspended.
func TestReturningFromAPagerReloads(t *testing.T) {
	m := logModel(t, "line")

	m, cmd := step(t, m, PagerExitMsg{})

