// ── The source's optional capabilities (Rule 130) ────────────────────────────

func TestTimestampsAndFollowAppearOnlyForASourceThatSupportsThem(t *testing.T) {
	capable := logModel(t, "line")
	for _, key := range []string{"t", "ctrl+f", "e"} {
